const e=[{id:"sv-5-bb001",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:1,stem:"An X̄ chart of **average MTTR per day** has CL = **4.2 h** and UCL = **5.7 h**. What is the standard deviation of the plotted statistic (one sigma on the chart)?",options:["1.5 h","0.25 h","0.5 h","0.75 h"],answer:2,hint:"Control limits sit 3 sigma (of the plotted statistic) from the centre line: σ = (UCL − CL) ÷ 3.",steps:[{title:"Given",body:"CL = 4.2, UCL = 5.7."},{title:"Formula",body:"$$\\sigma_{plot}=\\dfrac{UCL-CL}{3}$$"},{title:"Compute",body:"$$\\sigma_{plot}=\\dfrac{5.7-4.2}{3}=\\dfrac{1.5}{3}=0.5\\text{ h}$$"},{title:"Note",body:"For an X̄ chart this is the standard error of the subgroup mean, not the σ of individual values."}],final:"σ = 0.5 h → answer **C**",whyWrong:["This is the full distance from CL to UCL, which is three sigma.","Dividing by 6 gives one sigma only when you start from the full UCL − LCL width.","","The limits are at ±3σ, not ±2σ."],trap:"On an X̄ chart, one chart-sigma is σ ÷ √n, not the process σ.",bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb002",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:1,stem:"An X̄ chart of **subgroup mean of API latency** has CL = **180 ms** and UCL = **204 ms**. What is the standard deviation of the plotted statistic (one sigma on the chart)?",options:["8 ms","24 ms","4 ms","12 ms"],answer:0,hint:"Control limits sit 3 sigma (of the plotted statistic) from the centre line: σ = (UCL − CL) ÷ 3.",steps:[{title:"Given",body:"CL = 180, UCL = 204."},{title:"Formula",body:"$$\\sigma_{plot}=\\dfrac{UCL-CL}{3}$$"},{title:"Compute",body:"$$\\sigma_{plot}=\\dfrac{204-180}{3}=\\dfrac{24}{3}=8\\text{ ms}$$"},{title:"Note",body:"For an X̄ chart this is the standard error of the subgroup mean, not the σ of individual values."}],final:"σ = 8 ms → answer **A**",whyWrong:["","This is the full distance from CL to UCL, which is three sigma.","Dividing by 6 gives one sigma only when you start from the full UCL − LCL width.","The limits are at ±3σ, not ±2σ."],trap:"On an X̄ chart, one chart-sigma is σ ÷ √n, not the process σ.",bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb003",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:1,stem:"An I chart of **daily ticket backlog** has CL = **120** and UCL = **135**. Where are the upper boundaries of **zone C** and **zone B**?",options:["Zone C up to 130; zone B up to 135","Zone C up to 127.5; zone B up to 135","Zone C up to 121.7; zone B up to 123.3","Zone C up to 125; zone B up to 130"],answer:3,hint:"Zones: C = CL to ±1σ, B = ±1σ to ±2σ, A = ±2σ to ±3σ (the limit).",steps:[{title:"One sigma",body:"$$\\sigma=\\dfrac{135-120}{3}=5$$"},{title:"Zone C boundary",body:"$$CL+1\\sigma=120+5=125$$"},{title:"Zone B boundary",body:"$$CL+2\\sigma=120+2\\times 5=130$$"},{title:"Zone A",body:"From 130 up to the UCL at 135."}],final:"C ≤ 125, B ≤ 130 → answer **D**",whyWrong:["The zones were shifted up by one sigma: zone C is the band nearest the centre line (CL to +1σ).","The CL–UCL distance was split in two halves; it is split into three equal one-sigma zones.","Sigma was divided by 3 twice; one sigma is (UCL − CL) ÷ 3.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb004",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:2,stem:"An I chart of **weekly fibre-repair hours** has CL = **48** and UCL = **57**. Where are the upper boundaries of **zone C** and **zone B**?",options:["Zone C up to 54; zone B up to 57","Zone C up to 52.5; zone B up to 57","Zone C up to 49; zone B up to 50","Zone C up to 51; zone B up to 54"],answer:3,hint:"Zones: C = CL to ±1σ, B = ±1σ to ±2σ, A = ±2σ to ±3σ (the limit).",steps:[{title:"One sigma",body:"$$\\sigma=\\dfrac{57-48}{3}=3$$"},{title:"Zone C boundary",body:"$$CL+1\\sigma=48+3=51$$"},{title:"Zone B boundary",body:"$$CL+2\\sigma=48+2\\times 3=54$$"},{title:"Zone A",body:"From 54 up to the UCL at 57."}],final:"C ≤ 51, B ≤ 54 → answer **D**",whyWrong:["The zones were shifted up by one sigma: zone C is the band nearest the centre line (CL to +1σ).","The CL–UCL distance was split in two halves; it is split into three equal one-sigma zones.","Sigma was divided by 3 twice; one sigma is (UCL − CL) ÷ 3.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb005",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:1,stem:"On an X̄ chart for **call-handling time (s)** with CL = **50** and UCL = **62**, a subgroup mean of **59.5** is plotted. Which zone is it in?",options:["Zone B (between +1σ and +2σ)","Zone C (within ±1σ)","Zone A (between +2σ and +3σ)","Beyond the upper control limit"],answer:2,hint:"Find σ = (UCL − CL) ÷ 3, then how many sigmas the point is from CL.",steps:[{title:"One sigma",body:"$$\\sigma=\\dfrac{62-50}{3}=4$$"},{title:"Distance in sigmas",body:"$$z=\\dfrac{59.5-50}{4}=2.375$$"},{title:"Zone",body:"Between 2 and 3 sigma → zone A. One point in zone A is not a signal alone; Minitab Test 5 flags 2 of 3 consecutive points in zone A (same side)."}],final:"Zone A → answer **C**",whyWrong:["Zone B ends at 58; 59.5 is above it.","Zone C ends at 54.","","59.5 is below the UCL of 62."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb006",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:2,stem:"A c chart of **major alarms per night** has c̄ = **4**. What lower control limit will be drawn?",options:["−2.00","0 (the calculated LCL is negative)","−8.00","2.00"],answer:1,hint:"c chart: LCL = c̄ − 3√c̄; if negative, LCL = 0.",steps:[{title:"Formula",body:"$$LCL=\\bar c-3\\sqrt{\\bar c}$$"},{title:"Compute",body:"$$LCL=4-3\\times\\sqrt{4}=4-6=-2.00$$"},{title:"Decide",body:"Counts cannot fall below 0, so the LCL is set to 0. The chart then has an upper limit only, and runs below the centre line are judged by the run rules."}],final:"LCL = 0 → answer **B**",whyWrong:["A count cannot be negative, so a negative LCL is set to 0 (no lower limit).","","The formula uses √c̄, not c̄.","Only one √c̄ was subtracted; the limit is at three."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb007",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:2,stem:"A c chart of **billing complaints per day** has c̄ = **6.25**. What lower control limit will be drawn?",options:["0 (the calculated LCL is negative)","−1.25","−12.50","3.75"],answer:0,hint:"c chart: LCL = c̄ − 3√c̄; if negative, LCL = 0.",steps:[{title:"Formula",body:"$$LCL=\\bar c-3\\sqrt{\\bar c}$$"},{title:"Compute",body:"$$LCL=6.25-3\\times\\sqrt{6.25}=6.25-7.5=-1.25$$"},{title:"Decide",body:"Counts cannot fall below 0, so the LCL is set to 0. The chart then has an upper limit only, and runs below the centre line are judged by the run rules."}],final:"LCL = 0 → answer **A**",whyWrong:["","A count cannot be negative, so a negative LCL is set to 0 (no lower limit).","The formula uses √c̄, not c̄.","Only one √c̄ was subtracted; the limit is at three."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb008",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:1,stem:"An I chart for **daily change failures** has UCL = **8.6** and LCL = **2.6**. What are the centre line and one sigma?",options:["CL = 5.6, σ = 1","CL = 5.6, σ = 2","CL = 6, σ = 1","CL = 5.6, σ = 3"],answer:0,hint:"Symmetric limits: CL = (UCL + LCL) ÷ 2; σ = (UCL − LCL) ÷ 6.",steps:[{title:"Centre line",body:"$$CL=\\dfrac{8.6+2.6}{2}=5.6$$"},{title:"Sigma",body:"$$\\sigma=\\dfrac{8.6-2.6}{6}=1$$"}],final:"CL 5.6, σ 1 → answer **A**",whyWrong:["","UCL − LCL spans 6 sigma, so divide by 6, not 3.","The CL is the midpoint of the limits (their average), not their difference.","The limits are 3 sigma either side of CL."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb009",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:2,stem:"With ±3σ limits and only Test 1 (a point beyond a limit), what is the probability that a single point from a stable, normally distributed process falls **outside** the limits, and the average run length between false alarms?",options:["0.135%; about 741 points","5%; about 20 points","4.55%; about 22 points","0.27%; about 370 points"],answer:3,hint:"P(outside ±3σ) = 2 × P(Z > 3); ARL₀ = 1 ÷ P.",steps:[{title:"Tail area",body:"$$P=2\\times P(Z>3)=2\\times 0.00135=0.0027$$"},{title:"ARL",body:"$$ARL_0=\\dfrac{1}{0.0027}\\approx 370$$"},{title:"Meaning",body:"On average a stable process gives one false alarm every 370 points. Adding more run rules raises the false-alarm rate."}],final:"0.27%, ARL ≈ 370 → answer **D**",whyWrong:["Only one tail was counted; a point can fall beyond either limit.","That is the usual α for hypothesis tests, not the ±3σ false-alarm rate.","These are the figures for ±2σ limits.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb010",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:2,stem:"An I chart for **router CPU (%)** has CL = 50 and σ = 4 (UCL = 62). The last four points are 53, 61, 58, 60. Which Minitab test is triggered?",options:["Test 1: a point beyond 3σ","Test 2: 9 points in a row on the same side","Test 5: 2 out of 3 consecutive points more than 2σ from the centre line (same side)","Test 3: 6 points in a row all increasing"],answer:2,hint:"Compute each point’s z = (x − CL) ÷ σ; zone A is between 2σ and 3σ.",steps:[{title:"z-values",body:"$$\\dfrac{53-50}{4}=0.75\\quad \\dfrac{61-50}{4}=2.75\\quad \\dfrac{58-50}{4}=2\\quad \\dfrac{60-50}{4}=2.5$$"},{title:"Zone A points",body:"Beyond +2σ (z > 2): 61 (z = 2.75) and 60 (z = 2.5). The point 58 sits exactly on the 2σ line, not beyond it. So in the last three points, two are beyond 2σ on the upper side."},{title:"Decide",body:"Two of three consecutive points beyond 2σ, same side → Test 5. Investigate a possible upward shift."}],final:"Test 5 → answer **C**",whyWrong:["No point exceeds the UCL of 62.","Only four points are listed.","","The points go up and down, and there are only four."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb011",phase:5,topic:"5.2.11",qtype:"concept",difficulty:1,stem:"Which elements make up the basic **anatomy** of a Shewhart control chart?",options:["Specification limits, a target and a histogram of the data","A plotted statistic in time order, a centre line, and upper and lower control limits calculated from the process data","A Pareto bar for each defect type and a cumulative line","A regression line with confidence bands"],answer:1,hint:"Control chart = run chart + centre line + statistically calculated limits.",steps:[{title:"Key idea",body:"Points (individual values or subgroup statistics) are plotted in time order. The centre line is the process average of the statistic; the control limits sit about 3 sigma either side."},{title:"Purpose",body:"The chart separates common-cause from special-cause variation."}],final:"Statistic, CL, UCL, LCL → answer **B**",whyWrong:["Specification limits and histograms belong to capability analysis, not to a control chart.","","That describes a Pareto chart.","That is a fitted line plot."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb012",phase:5,topic:"5.2.11",qtype:"concept",difficulty:1,stem:"What is the key difference between **control limits** and **specification limits**?",options:["Control limits are always narrower than specification limits","Control limits come from the process data (voice of the process); specification limits come from the customer (voice of the customer)","Specification limits are calculated as the mean ± 3σ","They are the same thing with different names"],answer:1,hint:"VOP (control limits) vs VOC (spec limits).",steps:[{title:"Key idea",body:"Control limits show what the process actually does when it is stable. Specification limits show what the customer needs."},{title:"Consequence",body:"A process can be in control but not capable, or capable but out of control."}],final:"VOP vs VOC → answer **B**",whyWrong:["Control limits can be wider or narrower depending on how capable the process is.","","That is how control limits are calculated.","They have different sources and purposes."],trap:"Never draw specification limits on an X̄ chart: they apply to individual values, not subgroup means.",bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb013",phase:5,topic:"5.2.11",qtype:"concept",difficulty:1,stem:"On a control chart, what does the **horizontal axis** normally represent?",options:["The size of each subgroup","The specification range","The frequency of each value","Time order — the sequence of individual observations or subgroups"],answer:3,hint:"x-axis = order of production / time; y-axis = the plotted statistic.",steps:[{title:"Key idea",body:"Keeping the time order is what lets the chart show shifts, trends and cycles."},{title:"Apply",body:"Each point might be one day, one shift or one subgroup of five calls."}],final:"Time order → answer **D**",whyWrong:["Subgroup size is fixed or shown separately; the axis is sequence.","Specifications are on the vertical (measurement) scale, if shown at all.","Frequency is shown on a histogram.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb014",phase:5,topic:"5.2.11",qtype:"concept",difficulty:2,stem:"Why are Shewhart control limits usually set at **±3 sigma** of the plotted statistic?",options:["It balances a low false-alarm rate (about 0.27% per point for a stable normal process) against the ability to detect real shifts","Because 3σ limits guarantee zero defects","Because customers usually set specifications at ±3σ","Because 3σ makes the chart detect every small shift immediately"],answer:0,hint:"±3σ: economic balance of type I (false alarm) and type II (missed signal) errors.",steps:[{title:"Key idea",body:"Narrower limits catch shifts sooner but give more false alarms; wider limits do the opposite. Shewhart chose 3σ as a practical balance."},{title:"Numbers",body:"P(point beyond ±3σ | stable) ≈ 0.0027 → ARL₀ ≈ 370."}],final:"Balance false alarms and detection → answer **A**",whyWrong:["","Control limits say nothing about defects against specifications.","Control limits are not linked to customer specifications.","Small shifts are detected slowly by a Shewhart chart; CUSUM or EWMA work better for them."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb015",phase:5,topic:"5.2.11",qtype:"concept",difficulty:1,stem:"In the zone method for control charts, what is **zone C**?",options:["The band between 2σ and 3σ from the centre line","The band between 1σ and 2σ from the centre line","The band within ±1σ of the centre line","The area beyond the control limits"],answer:2,hint:"C (±1σ) – B (1–2σ) – A (2–3σ), counting outward from the centre line.",steps:[{title:"Key idea",body:"Each half of the chart is split into three equal one-sigma zones. About 68% of points fall in zone C for a stable normal process."},{title:"Use",body:"Run rules such as “15 points in a row in zone C” or “2 of 3 in zone A” use these zones."}],final:"Within ±1σ → answer **C**",whyWrong:["That is zone A.","That is zone B.","","Points beyond the limits trigger Test 1; that area is not a zone."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb016",phase:5,topic:"5.2.11",qtype:"scenario",difficulty:2,stem:"An I chart of **daily P1 incident count** shows **9 points in a row below the centre line** after a new monitoring tool went live, with no point beyond the limits. What does this indicate?",options:["Nothing, because no point is outside the control limits","A measurement error, because points should alternate above and below","The control limits are wrong and must be widened","A special cause: a likely downward shift in the process (Minitab Test 2), probably linked to the new tool"],answer:3,hint:"Minitab Test 2: 9 points in a row on the same side of the centre line.",steps:[{title:"Key idea",body:"For a stable process the chance of 9 points in a row on one side is about $$2\\times 0.5^9\\approx 0.004$$ so such a run is a signal."},{title:"Action",body:"Confirm the tool is the cause. If the improvement is sustained, recalculate the limits from the new data (with a note on the chart)."}],final:"Process shift (Test 2) → answer **D**",whyWrong:["Run rules detect non-random patterns even inside the limits.","Points should be random, not alternating; a long run on one side is the signal.","Widening limits hides the signal; the pattern shows a real change.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb017",phase:5,topic:"5.2.11",qtype:"scenario",difficulty:2,stem:"An I chart for **fibre-splice loss** shows **6 points in a row steadily increasing**. Which pattern is this and what is a likely cause?",options:["A shift (Test 2), caused by a sudden change of operator","A trend (Minitab Test 3) — for example, gradual wear of the splicing electrodes","Stratification (Test 7), caused by mixing two machines","Normal random variation"],answer:1,hint:"Test 3: 6 points in a row all increasing or all decreasing.",steps:[{title:"Key idea",body:"A trend signals something changing gradually: wear, drift, fatigue, growing backlog."},{title:"Action",body:"Look for the gradual cause, e.g. electrode condition, and add a maintenance trigger to the control plan."}],final:"Trend (Test 3) → answer **B**",whyWrong:["A shift is a sudden step that stays on one side; a steady rise is a trend.","","Stratification shows as points hugging the centre line.","Six consecutive increases is unlikely by chance and is a run-rule signal."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb018",phase:5,topic:"5.2.11",qtype:"scenario",difficulty:3,stem:"An X̄ chart for **average handle time** shows **15 points in a row within ±1σ** of the centre line. Each subgroup contains one call from each of five different teams. What is the most likely explanation?",options:["Excellent control; the process has become very consistent","A trend caused by learning","Stratification (Test 7): the subgroups mix different teams, so the within-subgroup range is inflated and the limits are too wide","Over-adjustment by supervisors"],answer:2,hint:"Test 7: 15 points in a row within 1σ (zone C) → suspect stratified subgroups.",steps:[{title:"Key idea",body:"When each subgroup contains items from several different streams, the range within a subgroup includes the differences between streams. The limits become too wide, so points crowd the centre."},{title:"Fix",body:"Form rational subgroups from one team at a time, or chart each team separately."}],final:"Stratification (Test 7) → answer **C**",whyWrong:["Points hugging the centre line usually mean the limits are wrong, not that the process improved.","A trend shows as steadily rising or falling points.","","Over-adjustment tends to produce alternating or saw-tooth patterns (Test 4)."],trap:"Points hugging the centre line are a warning sign, not a success.",bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb019",phase:5,topic:"5.2.11",qtype:"scenario",difficulty:2,stem:"An I chart for **daily order-fallout rate** shows **8 points in a row on both sides of the centre line, none of them in zone C**. What pattern is this?",options:["A mixture (Minitab Test 8): data from two different process conditions are being plotted together","Stratification (Test 7)","A trend (Test 3)","A random pattern; no action needed"],answer:0,hint:"Test 8: 8 points in a row more than 1σ from the centre line (either side).",steps:[{title:"Key idea",body:"When points avoid the middle, two populations are probably mixed — e.g. weekdays vs weekends, or two order systems."},{title:"Action",body:"Stratify the data by the suspected source and chart each separately."}],final:"Mixture (Test 8) → answer **A**",whyWrong:["","Stratification is the opposite: points crowd zone C.","A trend is a steady rise or fall.","Avoiding zone C for 8 points in a row is unlikely by chance."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb020",phase:5,topic:"5.2.11",qtype:"scenario",difficulty:2,stem:"A chart of **NOC alarm counts per shift** shows **14 points in a row alternating up and down**. Which Minitab test fires, and what could cause it?",options:["Test 1 — a point beyond the control limits","Test 6 — 4 out of 5 points beyond 1σ","No test fires because alternating is random","Test 4 — a systematic alternation, e.g. two shifts with different practices plotted alternately, or over-adjustment"],answer:3,hint:"Test 4: 14 points in a row alternating up and down.",steps:[{title:"Key idea",body:"Systematic up-down patterns suggest two alternating sources (day/night shifts, two tools) or tampering."},{title:"Action",body:"Check how data are collected and whether operators adjust after every point."}],final:"Test 4 (alternation) → answer **D**",whyWrong:["No point needs to be outside the limits for this pattern.","Test 6 looks at distance from the centre, not alternation.","Fourteen strict alternations in a row is very unlikely by chance.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb021",phase:5,topic:"5.2.11",qtype:"best-action",difficulty:2,stem:"A new X̄–R chart is set up for **VoLTE call-setup time**. Before interpreting the X̄ chart, what should the analyst check FIRST?",options:["That the R chart is in control, because the X̄ chart limits are calculated from the average range","That all X̄ points are inside the specification limits","That the X̄ chart has at least one point beyond the limits","That the subgroup size is larger than 25"],answer:0,hint:"Read the dispersion chart (R or S) first; X̄ limits depend on R̄ (or S̄).",steps:[{title:"Key idea",body:"X̄ chart limits are X̿ ± A₂R̄. If the ranges are out of control, R̄ is not a stable estimate and the X̄ limits are meaningless."},{title:"Order",body:"Stabilize the spread first, then judge the location."}],final:"Check the R chart first → answer **A**",whyWrong:["","Specification limits do not belong on an X̄ chart.","Out-of-control points are not a prerequisite.","Typical subgroup sizes are 3–5; 25 is the usual number of subgroups."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb022",phase:5,topic:"5.2.11",qtype:"concept",difficulty:2,stem:"What is the difference between **Phase I** and **Phase II** use of a control chart?",options:["Phase I monitors the process; Phase II sets the limits","Phase I uses historical data to set trial limits and confirm stability; Phase II uses the fixed limits to monitor new data","Phase I uses specification limits; Phase II uses control limits","Phase I is for attribute data and Phase II for variables data"],answer:1,hint:"Phase I: establish (trial limits, remove assignable causes, recompute). Phase II: monitor with frozen limits.",steps:[{title:"Key idea",body:"In Phase I, points with known special causes are investigated and removed before final limits are set. In Phase II the limits stay fixed so that new changes can be detected."},{title:"Trap",body:"Recalculating limits continually in Phase II lets the chart drift with the process and hides shifts."}],final:"Set limits vs monitor → answer **B**",whyWrong:["The order is reversed.","","Neither phase uses specification limits as control limits.","Both phases apply to both data types."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb023",phase:5,topic:"5.2.11",qtype:"concept",difficulty:2,stem:"Why does adding **more run rules** (Tests 2–8) to a Shewhart chart need care?",options:["Extra rules make the control limits wider","Extra rules can only be used with attribute charts","Each extra rule increases sensitivity to small shifts but also increases the false-alarm rate","Extra rules remove the need for a centre line"],answer:2,hint:"More tests → more power and more false alarms.",steps:[{title:"Key idea",body:"Each test has its own small false-alarm probability. Using all eight together gives noticeably more false signals than Test 1 alone."},{title:"Practice",body:"Choose a few tests that match the likely failure modes and document them in the control plan."}],final:"Sensitivity vs false alarms → answer **C**",whyWrong:["Rules do not change the limits.","They are used mainly with variables charts.","","Most run rules are defined relative to the centre line."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb024",phase:5,topic:"5.2.11",qtype:"not-except",difficulty:2,stem:"All of the following belong on a standard Shewhart control chart EXCEPT:",options:["Customer specification limits on an X̄ chart","A centre line at the process average","Upper and lower control limits","Annotations of known events such as a software release"],answer:0,hint:"X̄ charts plot subgroup means; specs apply to individual values.",steps:[{title:"Key idea",body:"Specification limits on an X̄ chart are misleading because the spread of means is much narrower than the spread of individual values."},{title:"Where specs belong",body:"On a histogram or capability analysis, or (with caution) on an individuals chart."}],final:"Spec limits on X̄ do not belong → answer **A**",whyWrong:["","The centre line is a core element.","Control limits are core elements.","Annotations help explain signals and are recommended."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb025",phase:5,topic:"5.2.11",qtype:"missing-word",difficulty:1,stem:"Complete the sentence: “The centre line of a control chart is normally drawn at the [?] of the plotted statistic, calculated from the process data.”",options:["target value set by the customer","upper specification limit","maximum value","average (mean)"],answer:3,hint:"CL = mean of the plotted statistic (X̄, R̄, p̄, c̄ …).",steps:[{title:"Key idea",body:"For an X̄ chart CL = X̿; for an R chart CL = R̄; for a p chart CL = p̄; for a c chart CL = c̄."},{title:"Exception",body:"A standard-given chart may use a known target value, but that must be stated."}],final:"Average → answer **D**",whyWrong:["A target is not the same as the process average; the chart shows what the process actually does.","Specification limits do not set the centre line.","The maximum would put almost every point below the line.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb026",phase:5,topic:"5.2.11",qtype:"true-false",difficulty:1,stem:"True or false: a point inside the control limits can still be part of an out-of-control signal.",options:["True","False"],answer:0,hint:"Out of control = Test 1 OR any non-random pattern rule.",steps:[{title:"Key idea",body:"Control limits catch large, sudden changes. Patterns inside the limits reveal smaller shifts, trends and mixtures."},{title:"Example",body:"Nine consecutive points just above the centre line indicate an upward shift."}],final:"True → answer **True**",whyWrong:["","Run rules such as 9 points in a row on one side or 6 points trending detect special causes even when every point is inside the limits."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb027",phase:5,topic:"5.2.11",qtype:"true-false",difficulty:2,stem:"True or false: if a process is in statistical control, it must also be meeting its customer specifications.",options:["True","False"],answer:1,hint:"Stability ≠ capability.",steps:[{title:"Key idea",body:"The control chart compares the process with itself; capability compares it with the customer’s requirements."},{title:"Apply",body:"Check stability first, then Cp/Cpk or Pp/Ppk."}],final:"False → answer **False**",whyWrong:["In control means stable and predictable. A stable process can still produce output outside the specification limits if it is not capable.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb028",phase:5,topic:"5.2.11",qtype:"concept",difficulty:2,stem:"Why is a control chart for variables data usually shown as a **pair** of charts (e.g. X̄ and R)?",options:["Because one chart is for the upper limit and one for the lower limit","One chart tracks the location (average) of the process and the other tracks its spread, and either can change on its own","Because Minitab cannot draw a single chart","Because the second chart shows specification limits"],answer:1,hint:"Location chart (X̄ or I) + dispersion chart (R, S or MR).",steps:[{title:"Key idea",body:"A process can shift its mean while keeping its spread, or become more variable while keeping its mean. Two charts detect both kinds of change."},{title:"Order",body:"Interpret the dispersion chart first."}],final:"Location and spread → answer **B**",whyWrong:["Each chart has both limits.","","Single charts can be drawn; pairing is about information.","Neither chart should carry specification limits."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb029",phase:5,topic:"5.2.11",qtype:"best-action",difficulty:2,stem:"A point on the **I-MR chart of daily provisioning time** goes above the UCL on the day a new order-management release went live. What is the BEST immediate response?",options:["Recalculate the control limits to include the point","Ignore the point because it is only one day","Follow the response plan: investigate the special cause (the release), contain any customer impact, and record the finding on the chart","Adjust the process mean immediately without investigating"],answer:2,hint:"Signal → response plan: investigate, contain, correct, document.",steps:[{title:"Key idea",body:"A Test 1 signal means a special cause is very likely. The control plan’s reaction plan says who acts and how."},{title:"Document",body:"Annotate the chart so the event is not misread later."}],final:"Investigate and record → answer **C**",whyWrong:["Including a special-cause point would widen the limits and hide future signals.","A single point beyond the limits is a valid signal (Test 1).","","Adjusting without understanding the cause risks tampering."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb030",phase:5,topic:"5.2.11",qtype:"concept",difficulty:2,stem:"Which Minitab test detects **4 out of 5 consecutive points more than 1σ from the centre line on the same side**, and what does it usually indicate?",options:["Test 6 — a small, sustained shift in the process mean","Test 5 — a large spike","Test 7 — stratification","Test 4 — over-adjustment"],answer:0,hint:"Tests 5 and 6 are early warnings of shifts smaller than 3σ.",steps:[{title:"Key idea",body:"Points that keep landing in zone B or beyond on one side suggest the mean has moved by roughly 1σ."},{title:"Action",body:"Investigate before the shift becomes large enough to trigger Test 1."}],final:"Test 6 — small shift → answer **A**",whyWrong:["","Test 5 is 2 of 3 points beyond 2σ.","Test 7 is 15 points within 1σ.","Test 4 is 14 points alternating up and down."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb031",phase:5,topic:"5.2.11",qtype:"concept",difficulty:1,stem:"On an **attribute** chart such as a p chart with varying subgroup sizes, why do the control limits look like a **stepped** line?",options:["Because the centre line changes for every subgroup","Because Minitab rounds the limits","Because special causes move the limits","The limits depend on each subgroup’s size, so they are wider for small subgroups and narrower for large ones"],answer:3,hint:"p-chart limits: p̄ ± 3√(p̄(1 − p̄) ÷ nᵢ).",steps:[{title:"Key idea",body:"The standard error of a proportion shrinks as n grows, so each subgroup gets its own limits."},{title:"Read it",body:"Compare each point with its own limits, not with a neighbour’s."}],final:"Limits depend on nᵢ → answer **D**",whyWrong:["The centre line p̄ stays fixed; only the limits vary.","Rounding does not cause steps.","Limits are not moved by individual points.",""],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb032",phase:5,topic:"5.2.11",qtype:"statements",difficulty:2,stem:`Which statements about control-chart anatomy are correct?

1. The centre line is the average of the plotted statistic.
2. Control limits are placed about 3 standard errors of the plotted statistic from the centre line.
3. The LCL of a count chart can be negative.
4. Zones A, B and C are each one sigma wide.`,options:["1 and 3 only","1, 2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],answer:1,hint:"Negative LCL for counts or proportions → 0.",steps:[{title:"Check each",body:"1 True. 2 True — “3 sigma” means 3 standard errors of what is plotted. 3 False. 4 True."},{title:"Decide",body:"Statements 1, 2 and 4."}],final:"1, 2, 4 → answer **B**",whyWrong:["Statement 3 is false; statements 2 and 4 are true.","","Statement 3 is false and statement 1 is true.","Statement 3 is false: a negative calculated LCL is set to 0 because counts cannot be negative."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb033",phase:5,topic:"5.2.11",qtype:"calculation",difficulty:2,stem:"For a stable process with normally distributed plotted values, roughly what percentage of points should fall in **zone C** (within ±1σ) and in **zone A** (between 2σ and 3σ, both sides together)?",options:["Zone C ≈ 4.3%; zone A ≈ 68.3%","Zone C ≈ 95.4%; zone A ≈ 0.3%","Zone C ≈ 68.3%; zone A ≈ 4.3%","Zone C ≈ 33.3%; zone A ≈ 33.3%"],answer:2,hint:"Use the normal distribution: P(|Z| < 1) and P(2 < |Z| < 3).",steps:[{title:"Zone C",body:"$$P(-1<Z<1)=\\Phi(1)-\\Phi(-1)=0.8413-0.1587=0.6827$$"},{title:"Zone A",body:"$$2\\times[\\Phi(3)-\\Phi(2)]=2\\times(0.9987-0.9772)=0.0428$$"},{title:"Use",body:"Too many points in zone C (Test 7) or too few (Test 8) are both signs of a non-random pattern."}],final:"C ≈ 68.3%, A ≈ 4.3% → answer **C**",whyWrong:["The zones were swapped: zone C is the central band, which holds most points.","95.4% is within ±2σ (zones B and C together), and 0.3% is beyond ±3σ.","","The zones are equal in width, not in probability; the normal curve is highest near the centre."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb034",phase:5,topic:"5.2.11",qtype:"concept",difficulty:1,stem:"On an **X̄ chart**, what does each plotted point represent?",options:["The average of one rational subgroup (e.g. 5 calls sampled together)","One individual measurement","The range of one subgroup","The cumulative average of all data so far"],answer:0,hint:"X̄ chart point = subgroup mean; R chart point = subgroup range.",steps:[{title:"Key idea",body:"Each subgroup of n items gives one mean (X̄ chart) and one range or standard deviation (R or S chart)."},{title:"Consequence",body:"Because means vary less than individuals, X̄ limits are tighter than the spread of individual values."}],final:"A subgroup mean → answer **A**",whyWrong:["","Individual values are plotted on an I chart.","Ranges are plotted on the R chart.","Cumulative averages are not plotted on a Shewhart X̄ chart."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb035",phase:5,topic:"5.2.11",qtype:"scenario",difficulty:3,stem:"A c chart of **major network outages per week** has c̄ = 0.3. Almost every point is 0 and the LCL is 0, so the chart could never show an improvement. What is a better charting approach?",options:["Keep the c chart and add more run rules","Switch to a p chart of outages","Chart the time (or number of days) between outages, e.g. on an I chart or a rare-event (G or T) chart","Set the LCL at −1 so improvements can show"],answer:2,hint:"Rare events: chart the time between events instead of counts per period.",steps:[{title:"Key idea",body:"When events are rare, counts per period are mostly zero and the chart loses its power. Time between events is a continuous measure that grows when the process improves."},{title:"Tools",body:"Minitab offers G charts (opportunities between events) and T charts (time between events)."}],final:"Chart time between events → answer **C**",whyWrong:["With nearly all points at 0, extra rules still cannot detect a reduction.","There is no clear “number inspected” to form a proportion, and the problem of rare events remains.","","A count cannot be negative; this makes no statistical sense."],bookRef:"Syllabus 5.2.11"},{id:"sv-5-bb036",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:1,stem:"The process standard deviation of **call handle time** is σ = **12 s**. Subgroups of **n = 4** are plotted on an X̄ chart. What is the standard deviation of the subgroup means?",options:["3.000 s","12.000 s","24.000 s","6.000 s"],answer:3,hint:"Standard error of the mean: σ(X̄) = σ ÷ √n.",steps:[{title:"Given",body:"σ = 12, n = 4."},{title:"Formula",body:"$$\\sigma_{\\bar X}=\\dfrac{\\sigma}{\\sqrt n}$$"},{title:"Compute",body:"$$\\sigma_{\\bar X}=\\dfrac{12}{\\sqrt{4}}=\\dfrac{12}{2}=6.000$$"},{title:"Impact",body:"The X̄ chart limits are ±3 of these from the centre line, so larger subgroups give tighter limits and detect smaller shifts."}],final:"σ(X̄) = 6.000 s → answer **D**",whyWrong:["σ was divided by n instead of √n.","This is the σ of individual values; averaging reduces the spread.","σ was multiplied by √n instead of divided.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb037",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:1,stem:"The process standard deviation of **fibre-splice loss** is σ = **0.06 dB**. Subgroups of **n = 9** are plotted on an X̄ chart. What is the standard deviation of the subgroup means?",options:["0.007 dB","0.020 dB","0.060 dB","0.180 dB"],answer:1,hint:"Standard error of the mean: σ(X̄) = σ ÷ √n.",steps:[{title:"Given",body:"σ = 0.06, n = 9."},{title:"Formula",body:"$$\\sigma_{\\bar X}=\\dfrac{\\sigma}{\\sqrt n}$$"},{title:"Compute",body:"$$\\sigma_{\\bar X}=\\dfrac{0.06}{\\sqrt{9}}=\\dfrac{0.06}{3}=0.020$$"},{title:"Impact",body:"The X̄ chart limits are ±3 of these from the centre line, so larger subgroups give tighter limits and detect smaller shifts."}],final:"σ(X̄) = 0.020 dB → answer **B**",whyWrong:["σ was divided by n instead of √n.","","This is the σ of individual values; averaging reduces the spread.","σ was multiplied by √n instead of divided."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb038",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:2,stem:"The process standard deviation of **API latency** is σ = **15 ms**. Subgroups of **n = 5** are plotted on an X̄ chart. What is the standard deviation of the subgroup means?",options:["6.708 ms","3.000 ms","15.000 ms","33.541 ms"],answer:0,hint:"Standard error of the mean: σ(X̄) = σ ÷ √n.",steps:[{title:"Given",body:"σ = 15, n = 5."},{title:"Formula",body:"$$\\sigma_{\\bar X}=\\dfrac{\\sigma}{\\sqrt n}$$"},{title:"Compute",body:"$$\\sigma_{\\bar X}=\\dfrac{15}{\\sqrt{5}}=\\dfrac{15}{2.2361}=6.708$$"},{title:"Impact",body:"The X̄ chart limits are ±3 of these from the centre line, so larger subgroups give tighter limits and detect smaller shifts."}],final:"σ(X̄) = 6.708 ms → answer **A**",whyWrong:["","σ was divided by n instead of √n.","This is the σ of individual values; averaging reduces the spread.","σ was multiplied by √n instead of divided."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb039",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:2,stem:"An X̄ chart for **IPTV channel-change delay** uses subgroups of **n = 4**. If the subgroup size is increased to **n = 16** (same process σ), how does the distance between the control limits change?",options:["It becomes 0.25 of its old width (narrower)","It becomes 2 times wider","It does not change","It becomes 0.5 of its old width (narrower)"],answer:3,hint:"X̄ chart limit width = 6σ ÷ √n ⇒ ratio = √n₁ ÷ √n₂.",steps:[{title:"Width",body:"$$W=UCL-LCL=\\dfrac{6\\sigma}{\\sqrt n}$$"},{title:"Ratio",body:"$$\\dfrac{W_{new}}{W_{old}}=\\dfrac{\\sqrt{4}}{\\sqrt{16}}=0.5000$$"},{title:"Meaning",body:"Quadrupling n halves the width; the chart becomes more sensitive to shifts in the mean, at the cost of more sampling."}],final:"× 0.5 → answer **D**",whyWrong:["The width scales with 1 ÷ √n, not 1 ÷ n.","Larger subgroups make the limits narrower, not wider.","The limits depend on σ ÷ √n, so they change with n.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb040",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:2,stem:"An X̄ chart for **IPTV channel-change delay** uses subgroups of **n = 3**. If the subgroup size is increased to **n = 12** (same process σ), how does the distance between the control limits change?",options:["It becomes 0.25 of its old width (narrower)","It becomes 2 times wider","It becomes 0.5 of its old width (narrower)","It does not change"],answer:2,hint:"X̄ chart limit width = 6σ ÷ √n ⇒ ratio = √n₁ ÷ √n₂.",steps:[{title:"Width",body:"$$W=UCL-LCL=\\dfrac{6\\sigma}{\\sqrt n}$$"},{title:"Ratio",body:"$$\\dfrac{W_{new}}{W_{old}}=\\dfrac{\\sqrt{3}}{\\sqrt{12}}=0.5000$$"},{title:"Meaning",body:"Quadrupling n halves the width; the chart becomes more sensitive to shifts in the mean, at the cost of more sampling."}],final:"× 0.5 → answer **C**",whyWrong:["The width scales with 1 ÷ √n, not 1 ÷ n.","Larger subgroups make the limits narrower, not wider.","","The limits depend on σ ÷ √n, so they change with n."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb041",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:1,stem:"A contact centre knows its average handle time is μ = **240 s** with σ = **30 s** (stable). What are the X̄ chart limits for subgroups of **n = 4** calls?",options:["LCL = 150, UCL = 330","LCL = 195, UCL = 285","LCL = 217.5, UCL = 262.5","LCL = 225, UCL = 255"],answer:1,hint:"Known μ and σ: X̄ limits = μ ± 3σ ÷ √n.",steps:[{title:"Standard error",body:"$$\\dfrac{\\sigma}{\\sqrt n}=\\dfrac{30}{\\sqrt{4}}=15$$"},{title:"Limits",body:"$$\\mu\\pm 3\\times 15=240\\pm 45$$"},{title:"Result",body:"LCL = 195 s, UCL = 285 s."}],final:"195 to 285 → answer **B**",whyWrong:["These are limits for individual calls; the X̄ chart uses σ ÷ √n.","","σ was divided by n instead of √n.","These are ±1 standard error; control limits are at ±3."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb042",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:3,stem:"The mean of **ticket resolution time** shifts up by **1σ** (σ = process standard deviation). With an I chart (n = 1) and only Test 1, what is the probability that the **next** point signals, and the average run length (ARL) to detect the shift?",options:["P ≈ 0.0013; ARL ≈ 740.8","P ≈ 0.0228; ARL ≈ 43.9","P ≈ 0.1587; ARL ≈ 6.3","P ≈ 0.9772; ARL ≈ 1.02"],answer:1,hint:"Shift in chart units = δ√n. P(signal) = P(Z > 3 − δ√n) + P(Z < −3 − δ√n); ARL = 1 ÷ P.",steps:[{title:"Shift in standard errors",body:"$$\\delta\\sqrt n=1\\times\\sqrt{1}=1$$"},{title:"Probability",body:"$$P=P(Z>3-1)+P(Z<-3-1)=0.0228+0.00003=0.0228$$"},{title:"ARL",body:"$$ARL=\\dfrac{1}{0.0228}\\approx 43.9$$ points (subgroups)."},{title:"Lesson",body:"Larger subgroups detect the same shift much sooner (compare n = 1 and n = 4). CUSUM or EWMA charts are another option for small shifts."}],final:"P ≈ 0.0228, ARL ≈ 43.9 → answer **B**",whyWrong:["This is the false-alarm probability for one limit with no shift.","","The limit is at 3 standard errors, not 2.","This is the probability of NOT signalling (β); P(signal) is its complement."],trap:"A Shewhart chart with n = 1 can take dozens of points to catch a 1σ shift.",bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb043",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:3,stem:"The mean of **ticket resolution time** shifts up by **1σ** (σ = process standard deviation). With an X̄ chart with n = 4 and only Test 1, what is the probability that the **next** point signals, and the average run length (ARL) to detect the shift?",options:["P ≈ 0.0013; ARL ≈ 740.8","P ≈ 0.0228; ARL ≈ 44.0","P ≈ 0.1587; ARL ≈ 6.3","P ≈ 0.8413; ARL ≈ 1.19"],answer:2,hint:"Shift in chart units = δ√n. P(signal) = P(Z > 3 − δ√n) + P(Z < −3 − δ√n); ARL = 1 ÷ P.",steps:[{title:"Shift in standard errors",body:"$$\\delta\\sqrt n=1\\times\\sqrt{4}=2$$"},{title:"Probability",body:"$$P=P(Z>3-2)+P(Z<-3-2)=0.1587+0.00000=0.1587$$"},{title:"ARL",body:"$$ARL=\\dfrac{1}{0.1587}\\approx 6.3$$ points (subgroups)."},{title:"Lesson",body:"Larger subgroups detect the same shift much sooner (compare n = 1 and n = 4). CUSUM or EWMA charts are another option for small shifts."}],final:"P ≈ 0.1587, ARL ≈ 6.3 → answer **C**",whyWrong:["This is the false-alarm probability for one limit with no shift.","The subgroup size was ignored: on an X̄ chart the shift in standard-error units is δ√n.","","This is the probability of NOT signalling (β); P(signal) is its complement."],trap:"A Shewhart chart with n = 1 can take dozens of points to catch a 1σ shift.",bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb044",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:1,stem:"A NOC samples **5 consecutive alarms** every **30 minutes**, around the clock, to chart alarm-acknowledgement time. How many subgroups and how many alarms are sampled per day?",options:["24 subgroups, 120 alarms","48 subgroups, 48 alarms","240 subgroups, 1200 alarms","48 subgroups, 240 alarms"],answer:3,hint:"Subgroups per day = minutes per day ÷ interval; units = subgroups × n.",steps:[{title:"Subgroups",body:"$$\\dfrac{24\\times 60}{30}=48$$"},{title:"Units",body:"$$48\\times 5=240$$"},{title:"Check the plan",body:"Is this frequency needed? It should match how fast the process can change and the cost of missing a shift."}],final:"48 subgroups, 240 alarms → answer **D**",whyWrong:["Sampling every 30 minutes gives two subgroups per hour, not one.","Each subgroup contains 5 alarms.","The number of subgroups was multiplied by n twice.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb045",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:1,stem:"An X̄–R chart for **router boot time (s)** uses subgroups of **n = 5** and has R̄ = **6.98**. What is the estimate of the **within-subgroup** standard deviation? (d₂ = 2.326)",options:["3.001 s","16.235 s","3.122 s","1.342 s"],answer:0,hint:"σ(within) = R̄ ÷ d₂.",steps:[{title:"Formula",body:"$$\\hat\\sigma_{within}=\\dfrac{\\bar R}{d_2}$$"},{title:"Compute",body:"$$\\hat\\sigma=\\dfrac{6.98}{2.326}=3.001$$"},{title:"Meaning",body:"This captures only short-term (within-subgroup) variation, which is why rational subgroups matter: if subgroups mix sources, R̄ and σ(within) are inflated."}],final:"σ = 3.001 s → answer **A**",whyWrong:["","R̄ was multiplied by d₂ instead of divided.","R̄ was divided by √n; the conversion constant from range to σ is d₂.","This is σ ÷ √n, the standard error of the subgroup mean, not σ within."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb046",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:2,stem:"An X̄–R chart for **router boot time (s)** uses subgroups of **n = 3** and has R̄ = **2.47**. What is the estimate of the **within-subgroup** standard deviation? (d₂ = 1.693)",options:["4.182 s","1.426 s","1.459 s","0.842 s"],answer:2,hint:"σ(within) = R̄ ÷ d₂.",steps:[{title:"Formula",body:"$$\\hat\\sigma_{within}=\\dfrac{\\bar R}{d_2}$$"},{title:"Compute",body:"$$\\hat\\sigma=\\dfrac{2.47}{1.693}=1.459$$"},{title:"Meaning",body:"This captures only short-term (within-subgroup) variation, which is why rational subgroups matter: if subgroups mix sources, R̄ and σ(within) are inflated."}],final:"σ = 1.459 s → answer **C**",whyWrong:["R̄ was multiplied by d₂ instead of divided.","R̄ was divided by √n; the conversion constant from range to σ is d₂.","","This is σ ÷ √n, the standard error of the subgroup mean, not σ within."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb047",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:2,stem:"After a shift, each subgroup on an X̄ chart has a probability of **0.1587** of signalling. What is the probability that the shift is detected **within the next 5 subgroups**?",options:["0.579","0.794","0.421","0.080"],answer:0,hint:"P(detect within k) = 1 − (1 − p)^k.",steps:[{title:"No signal in one subgroup",body:"$$1-p=1-0.1587=0.8413$$"},{title:"No signal in five",body:"$$(1-p)^5=0.8413\\times 0.8413\\times 0.8413\\times 0.8413\\times 0.8413=0.421$$"},{title:"Detect within five",body:"$$1-0.421=0.579$$"},{title:"Use",body:"This shows how sampling frequency translates into detection time: more frequent subgroups shorten the time to signal."}],final:"≈ 0.579 → answer **A**",whyWrong:["","The probabilities were added; use 1 − P(no signal in all 5).","This is the probability of NOT detecting the shift in 5 subgroups.","This is the probability that the FIRST signal comes exactly at subgroup 5, not within 5."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb048",phase:5,topic:"5.2.12",qtype:"concept",difficulty:1,stem:"What is a **rational subgroup**?",options:["A random sample taken from a whole day’s output","A group of measurements taken under essentially the same conditions, so that variation within it reflects only common causes","A subgroup that contains one item from every machine or team","Any group of exactly five measurements"],answer:1,hint:"Rational subgroup: minimize the chance of special causes inside a subgroup; maximize the chance between subgroups.",steps:[{title:"Key idea",body:"Within-subgroup variation sets the control limits. If only common causes act within subgroups, the limits are tight and any special cause shows up as differences between subgroups."},{title:"Typical choice",body:"Consecutive units from one stream, close together in time."}],final:"Same conditions → common cause only → answer **B**",whyWrong:["Spreading a subgroup across the day mixes in shifts and drifts, which inflates within-subgroup variation.","","That deliberately mixes sources and causes stratification.","Size alone does not make a subgroup rational."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb049",phase:5,topic:"5.2.12",qtype:"scenario",difficulty:2,stem:"A Black Belt forms X̄–R subgroups by taking **one call from each of the 5 contact-centre teams** at 10:00 each day. The X̄ chart shows almost all points close to the centre line. What is wrong?",options:["Nothing; points near the centre line show excellent control","The subgroup size is too large","The chart should use specification limits instead","The subgroups mix teams, so the ranges include team-to-team differences; the limits are too wide and the chart is insensitive"],answer:3,hint:"Mixed streams in a subgroup → inflated R̄ → wide limits → stratification pattern.",steps:[{title:"Key idea",body:"Differences between teams are a likely special cause; putting them inside every subgroup hides them in R̄."},{title:"Fix",body:"Subgroup within one team at a time (or chart teams separately), so team differences appear between subgroups."}],final:"Mixed subgroups inflate limits → answer **D**",whyWrong:["Hugging the centre line usually means the limits are inflated, not that control is excellent.","n = 5 is normal; the problem is what goes into each subgroup.","Specification limits do not fix the subgroup problem.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb050",phase:5,topic:"5.2.12",qtype:"concept",difficulty:2,stem:"How should **sampling frequency** for a control chart be chosen?",options:["Once a month for every process, to keep things simple","Often enough to detect a change before it causes significant harm — in line with how quickly the process can change and the cost of sampling","As often as possible, regardless of cost","Only when a defect is reported"],answer:1,hint:"Frequency ↔ rate of process change, risk, cost of sampling.",steps:[{title:"Key idea",body:"If a process can drift within an hour, daily sampling is too slow. If it changes only with monthly releases, hourly sampling wastes effort."},{title:"Practice",body:"Sample more often at start-up or after changes, then reduce frequency once stability is shown."}],final:"Match frequency to the rate of change → answer **B**",whyWrong:["A fast-changing process could produce many bad units between samples.","","Sampling has a cost, and very frequent samples can be autocorrelated.","That is reactive inspection, not process control."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb051",phase:5,topic:"5.2.12",qtype:"concept",difficulty:2,stem:"What is the effect of **increasing the subgroup size** n on an X̄ chart (same σ)?",options:["The limits get closer to the centre line, so smaller shifts in the mean are detected faster, but each sample costs more","The limits get wider, so the chart gives fewer false alarms","The centre line moves","The R chart is no longer needed"],answer:0,hint:"Limits ∝ 1 ÷ √n.",steps:[{title:"Key idea",body:"σ(X̄) = σ ÷ √n, so larger subgroups give a more precise mean and tighter limits."},{title:"Trade-off",body:"More measurements per subgroup cost more; for n above about 10, use an S chart instead of an R chart."}],final:"Tighter limits, faster detection → answer **A**",whyWrong:["","Larger n narrows the limits; the false-alarm rate stays about the same.","The centre line is the process average; n does not change it.","The spread still needs monitoring."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb052",phase:5,topic:"5.2.12",qtype:"concept",difficulty:2,stem:"Variation on an X̄–R chart can be split into two parts. Which part do the **X̄ chart limits** measure, and which part do the **plotted X̄ points** reveal?",options:["The limits measure between-subgroup variation; the points reveal within-subgroup variation","Both measure total long-term variation","The limits measure within-subgroup (short-term) variation; the points reveal between-subgroup variation","The limits measure measurement error only"],answer:2,hint:"Limits from R̄ (within); signals from differences between subgroup means (between).",steps:[{title:"Key idea",body:"The chart asks: do subgroup means differ more than the within-subgroup noise predicts? If yes, there is extra between-subgroup (special-cause) variation."},{title:"Link",body:"This is why rational subgrouping is so important."}],final:"Within → limits; between → signals → answer **C**",whyWrong:["It is the other way round: limits come from R̄.","X̄–R limits deliberately use only within-subgroup variation.","","R̄ includes all short-term process variation, not just the gauge."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb053",phase:5,topic:"5.2.12",qtype:"best-action",difficulty:2,stem:"Daily performance data for **broadband speed tests** come as one value per day. A Black Belt wants to build an X̄–R chart by grouping **7 consecutive days** into each subgroup. What is the BEST advice?",options:["Group by 7 days; weekly subgroups are always rational","Group by 30 days to get more stable ranges","Plot only the weekly minimum","Use an I-MR chart of daily values instead; grouping a week mixes day-to-day changes into the subgroups and delays signals"],answer:3,hint:"One value per period and no natural subgroup → I-MR chart.",steps:[{title:"Key idea",body:"Subgroups should be formed from units made under the same conditions. Consecutive days may not be, and weekly grouping means a shift is seen only at week end."},{title:"Apply",body:"Chart each day on an I-MR chart; consider a weekday/weekend stratification if needed."}],final:"Use I-MR → answer **D**",whyWrong:["A week can contain weekday/weekend differences, which inflate the range.","Even wider grouping hides more special causes and slows detection further.","Minimum values discard information and have no standard Shewhart chart.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb054",phase:5,topic:"5.2.12",qtype:"concept",difficulty:2,stem:"Why can sampling **too frequently** cause problems on a Shewhart chart?",options:["Too many points always produce more out-of-control signals than are real","The chart needs specification limits when sampling is frequent","Frequent sampling reduces the subgroup size automatically","Successive points may be autocorrelated (not independent), which makes the standard limits misleading"],answer:3,hint:"Shewhart limits assume independent points; very frequent sampling of slow processes violates this.",steps:[{title:"Key idea",body:"If the process moves slowly, readings a few seconds apart are almost identical. Moving ranges are then small, limits too tight, and false alarms frequent."},{title:"Fix",body:"Sample less often, use time-series methods, or chart residuals of a time-series model."}],final:"Autocorrelation → answer **D**",whyWrong:["Not always; the issue is dependence between consecutive points.","Specifications do not fix dependence.","Subgroup size is chosen separately.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb055",phase:5,topic:"5.2.12",qtype:"scenario",difficulty:2,stem:"An X̄–R chart is planned for **order-entry time** in a centre that runs **morning and evening shifts** with different staffing. How should the subgroups be formed?",options:["Take each subgroup from a single shift (consecutive orders close in time), so shift differences appear between subgroups","Take half of each subgroup from each shift","Take one subgroup per day containing orders from the whole day","Ignore shifts because randomization removes their effect"],answer:0,hint:"Put potential special causes BETWEEN subgroups, not within them.",steps:[{title:"Key idea",body:"If the shifts differ, the X̄ chart will show it as alternating or clustered means — a useful signal."},{title:"Option",body:"If the difference is permanent and accepted, chart each shift separately."}],final:"One shift per subgroup → answer **A**",whyWrong:["","This puts the shift difference inside every subgroup and inflates R̄.","A full-day subgroup mixes both shifts and any drift.","Randomization is a DOE tool; for SPC, subgroups must be rational."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb056",phase:5,topic:"5.2.12",qtype:"true-false",difficulty:1,stem:"True or false: for an X̄–R chart, the subgroup size should normally be kept constant.",options:["True","False"],answer:0,hint:"Constants A₂, D₃, D₄ depend on n.",steps:[{title:"Key idea",body:"With varying n, every subgroup needs its own limits. An X̄–S chart handles varying sizes more naturally."},{title:"Practice",body:"Choose n (often 3–5) and keep it."}],final:"True → answer **True**",whyWrong:["","Constant n keeps the limits constant and easy to interpret; X̄–R constants depend on n."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb057",phase:5,topic:"5.2.12",qtype:"true-false",difficulty:2,stem:"True or false: a subgroup made of units collected over a long period (e.g. one unit every hour across the day) gives tighter control limits than a subgroup of consecutive units.",options:["True","False"],answer:1,hint:"Wider time window inside a subgroup → larger R̄ → wider limits.",steps:[{title:"Key idea",body:"Consecutive units capture only short-term common-cause variation."},{title:"Consequence",body:"Long-window subgroups make the chart less sensitive to the changes it is meant to detect."}],final:"False → answer **False**",whyWrong:["Units spread over time include more variation (drift, shifts), so the within-subgroup range grows and the limits become wider.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb058",phase:5,topic:"5.2.12",qtype:"not-except",difficulty:2,stem:"All of the following are good subgrouping practices EXCEPT:",options:["Taking consecutive units from one stream","Combining output from several different machines or teams in each subgroup","Keeping the subgroup size constant","Choosing subgroups so that suspected special causes fall between subgroups"],answer:1,hint:"Do not mix streams inside a subgroup.",steps:[{title:"Key idea",body:"Mixing streams inflates the within-subgroup variation and hides stream differences."},{title:"Instead",body:"Subgroup by stream, or chart each stream separately."}],final:"Mixing streams → answer **B**",whyWrong:["This keeps within-subgroup variation to common causes.","","This keeps limits simple and comparable.","This is the core of rational subgrouping."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb059",phase:5,topic:"5.2.12",qtype:"concept",difficulty:1,stem:"When is an **I-MR** chart preferred to an X̄–R chart?",options:["When the data are attribute counts","When subgroups of 5 are easy to collect","When there is only one measurement per time period or batch, so rational subgroups larger than 1 cannot be formed","When the specification limits are tight"],answer:2,hint:"n = 1 → I-MR.",steps:[{title:"Key idea",body:"Examples: one daily KPI value, one monthly billing-run time, one test per release."},{title:"Limit",body:"I charts are less sensitive to small shifts than X̄ charts, and more sensitive to non-normality."}],final:"One value per period → answer **C**",whyWrong:["Counts and proportions use c, u, p or np charts.","Then X̄–R is usually more sensitive.","","Specifications do not decide the chart type."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb060",phase:5,topic:"5.2.12",qtype:"scenario",difficulty:3,stem:"A team charts **average daily call-handle time** with an X̄–R chart, where each subgroup is all calls of the day (n ≈ 2,000). Almost every point is out of control. What is the most likely explanation?",options:["The process is truly out of control every day","With huge subgroups the limits are extremely tight and natural day-to-day variation (which is not in R̄) appears as signals; an I-MR chart of the daily averages is more suitable","The R chart constants are wrong for n = 2,000","The data must be non-normal"],answer:1,hint:"Very large subgroups → σ ÷ √n is tiny → between-day common variation looks like special cause.",steps:[{title:"Key idea",body:"The limits use only within-day variation divided by √2,000. Ordinary day-to-day variation is much bigger and is flagged."},{title:"Fix",body:"Treat each day’s average as one value and use an I-MR chart (its limits include day-to-day variation)."}],final:"Use I-MR of daily averages → answer **B**",whyWrong:["Day-to-day variation is normal; the chart only sees within-day variation as “common”.","","Constants are not the core issue; the subgrouping is.","With averages of 2,000 calls, the means are close to normal."],trap:"Bigger subgroups are not always better: limits can become unrealistically tight.",bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb061",phase:5,topic:"5.2.12",qtype:"best-action",difficulty:2,stem:"A new provisioning process has just been launched and its stability is unknown. How should the **sampling frequency** be set for its control chart?",options:["Sample frequently at first to learn how the process behaves, then reduce the frequency once stability is demonstrated","Sample rarely at first to save cost, then increase if problems appear","Use the same frequency as a mature process","Wait until the process is stable before sampling"],answer:0,hint:"Higher frequency during start-up or after changes; lower once proven stable.",steps:[{title:"Key idea",body:"Sampling frequency is a risk decision. Early on, the chance and cost of undetected shifts is high."},{title:"Document",body:"Record the frequency and the rule for changing it in the control plan."}],final:"Frequent first, then reduce → answer **A**",whyWrong:["","Problems could go unseen for long periods just when risk is highest.","A new process is less predictable and needs closer watching.","Stability can only be shown by sampling."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb062",phase:5,topic:"5.2.12",qtype:"concept",difficulty:2,stem:"Why might an **X̄–S** chart be chosen instead of X̄–R?",options:["Because X̄–S charts do not need subgroups","Because the range cannot be calculated for n > 10","For larger subgroups (roughly n > 10) or varying subgroup sizes, the standard deviation uses all data and estimates spread more efficiently than the range","Because X̄–S charts use specification limits"],answer:2,hint:"R for small n (2–9); S for larger or varying n.",steps:[{title:"Key idea",body:"The range uses only the largest and smallest values. As n grows, it wastes more information."},{title:"Apply",body:"Use S when subgroups are large or uneven (e.g. calls per hour)."}],final:"Large or varying n → answer **C**",whyWrong:["Both need subgroups.","It can, but it ignores the middle values and loses efficiency.","","Neither uses specification limits."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb063",phase:5,topic:"5.2.12",qtype:"missing-word",difficulty:1,stem:"Complete the sentence: “Subgroups should be chosen so that variation **within** subgroups is due only to [?] causes, while special causes show up as differences **between** subgroups.”",options:["special","assignable","measurement","common"],answer:3,hint:"Within = common; between = special.",steps:[{title:"Key idea",body:"This is the principle of rational subgrouping."},{title:"Result",body:"Tight limits that are sensitive to real changes."}],final:"Common → answer **D**",whyWrong:["Special causes should fall between subgroups, not within them.","Assignable is another name for special causes.","Measurement error is part of common-cause variation but is not the full answer.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb064",phase:5,topic:"5.2.12",qtype:"statements",difficulty:2,stem:`Which statements about subgroups and variation are correct?

1. Larger subgroups give narrower X̄ chart limits.
2. Mixing streams within a subgroup makes the chart more sensitive.
3. The R chart monitors within-subgroup variation.
4. Sampling frequency should reflect how quickly the process can change.`,options:["1 and 2 only","1, 3 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],answer:1,hint:"Rational subgroups, √n effect, frequency vs rate of change.",steps:[{title:"Check each",body:"1 True. 2 False. 3 True. 4 True."},{title:"Decide",body:"Statements 1, 3 and 4."}],final:"1, 3, 4 → answer **B**",whyWrong:["Statement 2 is false; statements 3 and 4 are true.","","Statement 2 is false and statement 1 is true.","Statement 2 is false: mixed streams inflate R̄ and make the chart less sensitive."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb065",phase:5,topic:"5.2.12",qtype:"concept",difficulty:2,stem:"What does **high between-subgroup variation** compared with within-subgroup variation suggest on an X̄–R chart?",options:["An excellent, stable process","A problem with the R chart constants","That the subgroup size should be reduced to 1","Special causes acting between subgroups — the X̄ chart will show points beyond the limits or non-random patterns"],answer:3,hint:"Between ≫ within → out of control on X̄.",steps:[{title:"Key idea",body:"If subgroup means vary more than the within-subgroup spread predicts, something changes from subgroup to subgroup."},{title:"Action",body:"Investigate what differs between those time periods (shift, release, staffing)."}],final:"Special causes between subgroups → answer **D**",whyWrong:["Stability means between-subgroup variation is consistent with within-subgroup noise.","The constants are fixed tables; the pattern is in the process.","Reducing n does not remove the special causes.",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb066",phase:5,topic:"5.2.12",qtype:"concept",difficulty:2,stem:"For the same total sampling effort, which plan generally detects a **sudden** mean shift **sooner**: subgroups of 5 every hour, or subgroups of 20 every 4 hours?",options:["Subgroups of 20 every 4 hours, because larger subgroups always detect shifts sooner","Both are always identical","Subgroups of 5 every hour, because the shift can be caught at the next hourly sample","Neither can detect sudden shifts"],answer:2,hint:"Detection time = time between samples × ARL; small frequent samples often win for large shifts.",steps:[{title:"Key idea",body:"For moderate-to-large shifts, small frequent subgroups usually detect sooner in clock time. For small shifts, larger subgroups (or CUSUM/EWMA) may be better."},{title:"Decide",body:"Balance shift size of interest, sampling cost and time between samples."}],final:"Small, frequent subgroups → answer **C**",whyWrong:["Larger subgroups give a higher detection probability per sample, but there are 4 hours between samples.","Same effort does not mean the same detection time.","","Both can; they differ in speed."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb067",phase:5,topic:"5.2.12",qtype:"concept",difficulty:1,stem:"How many subgroups are commonly recommended to establish **trial control limits** for an X̄–R chart?",options:["About 20–25 subgroups","2–3 subgroups","Exactly 5 subgroups","At least 1,000 subgroups"],answer:0,hint:"Rule of thumb: 20–25 subgroups (e.g. 100 individual values with n = 4–5).",steps:[{title:"Key idea",body:"Enough subgroups are needed to estimate the average and the average range with reasonable precision."},{title:"Then",body:"Investigate any signals, remove assignable causes and recalculate."}],final:"20–25 subgroups → answer **A**",whyWrong:["","Too few to estimate R̄ and X̿ reliably.","Five is a common subgroup SIZE, not the number of subgroups.","Far more than needed to set trial limits."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb068",phase:5,topic:"5.2.12",qtype:"calculation",difficulty:3,stem:"A Black Belt wants an X̄ chart (Test 1 only) to have about a **50% chance** of signalling on the very next subgroup after a **1σ** shift in **API response time**. What subgroup size n achieves this?",options:["3","4","9","6"],answer:2,hint:"P(signal) ≈ 0.5 when the shifted mean sits on the control limit: δ√n = 3.",steps:[{title:"Condition",body:"$$3-\\delta\\sqrt n=0\\Rightarrow\\sqrt n=\\dfrac{3}{\\delta}$$"},{title:"Compute",body:"$$\\sqrt n=\\dfrac{3}{1}=3\\Rightarrow n=3\\times 3=9$$"},{title:"Check",body:"$$P(Z>3-1\\times\\sqrt 9)=P(Z>0)=0.5\\Rightarrow ARL=2$$"}],final:"n = 9 → answer **C**",whyWrong:["This makes δ√n ≈ 1.73, not 3; √n (not n) must equal 3 ÷ δ.","With n = 4, δ√n = 2, so the probability is only about 16%.","","With n = 6, δ√n ≈ 2.45, so the probability is about 29%."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb069",phase:5,topic:"5.2.12",qtype:"concept",difficulty:2,stem:"How does subgrouping link control charts to **Cp/Cpk** versus **Pp/Ppk**?",options:["Cp and Cpk use overall σ; Pp and Ppk use within-subgroup σ","Both use exactly the same σ, so subgrouping does not matter","Cp uses the range of the specification only, not σ","Cp and Cpk use within-subgroup (short-term) σ such as R̄ ÷ d₂; Pp and Ppk use overall (long-term) σ from all data"],answer:3,hint:"σ(within) from subgroups → Cp/Cpk; σ(overall) → Pp/Ppk.",steps:[{title:"Key idea",body:"If the process is stable, within and overall σ are similar and Cpk ≈ Ppk. A big gap means between-subgroup (special-cause or shifting) variation."},{title:"Link",body:"Poor subgrouping (mixed streams) inflates σ(within) and makes Cp look worse than it should."}],final:"Within vs overall σ → answer **D**",whyWrong:["It is the other way round.","They differ precisely because of between-subgroup variation.","Cp = (USL − LSL) ÷ 6σ(within).",""],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb070",phase:5,topic:"5.2.12",qtype:"best-action",difficulty:2,stem:"Network latency has a strong **daily traffic cycle** (peaks at 20:00). Subgroups taken at **random times** give an X̄ chart that jumps up and down with many signals. What is the BEST action?",options:["Take subgroups at consistent times (or stratify peak vs off-peak) so the known cycle does not masquerade as special-cause variation","Widen the control limits to 4σ so the jumps stay inside","Stop charting latency because it is not stable","Average all subgroups of the day into one point and use an X̄–R chart with n = 1"],answer:0,hint:"Known, predictable cycles must be designed into the sampling plan (timing or stratification).",steps:[{title:"Key idea",body:"Random sampling times put a known, repeating effect between subgroups in an irregular way, creating false signals."},{title:"Fix",body:"Sample at the same time(s) each day, or chart peak and off-peak separately, so remaining signals point to real special causes."}],final:"Consistent timing or stratify → answer **A**",whyWrong:["","This hides real signals instead of fixing the sampling plan.","The cycle is predictable; the chart design should account for it.","An X̄–R chart needs n ≥ 2; and averaging hides when problems happen."],bookRef:"Syllabus 5.2.12"},{id:"sv-5-bb071",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:1,stem:"An I-MR chart of **daily P1 MTTR** has X̄ = **3.8 h** and M̄R = **0.9 h**. What are the control limits of the **Individuals** chart? (E₂ = 2.66)",options:["LCL = 1.10, UCL = 6.50","LCL = 1.41, UCL = 6.19","LCL = 0.86, UCL = 6.74","LCL = 2.60, UCL = 5.00"],answer:1,hint:"I chart: X̄ ± E₂·M̄R, with E₂ = 3 ÷ d₂ = 3 ÷ 1.128 ≈ 2.66.",steps:[{title:"Formula",body:"$$UCL=\\bar X+2.66\\,\\overline{MR}\\qquad LCL=\\bar X-2.66\\,\\overline{MR}$$"},{title:"Margin",body:"$$2.66\\times 0.9=2.394$$"},{title:"Limits",body:"$$UCL=3.8+2.394=6.19\\qquad LCL=3.8-2.394=1.41$$"}],final:"1.41 to 6.19 → answer **B**",whyWrong:["M̄R was used directly as sigma; it must first be divided by d₂ = 1.128 (or multiplied by E₂ = 2.66 = 3 ÷ 1.128).","","D₄ = 3.267 is for the MR chart UCL, not the I chart.","The moving range was halved; E₂ already includes the conversion from MR to sigma."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb072",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"An I-MR chart of **weekly billing-run time** has X̄ = **142 min** and M̄R = **11.5 min**. What are the control limits of the **Individuals** chart? (E₂ = 2.66)",options:["LCL = 111.41, UCL = 172.59","LCL = 107.50, UCL = 176.50","LCL = 104.43, UCL = 179.57","LCL = 126.70, UCL = 157.30"],answer:0,hint:"I chart: X̄ ± E₂·M̄R, with E₂ = 3 ÷ d₂ = 3 ÷ 1.128 ≈ 2.66.",steps:[{title:"Formula",body:"$$UCL=\\bar X+2.66\\,\\overline{MR}\\qquad LCL=\\bar X-2.66\\,\\overline{MR}$$"},{title:"Margin",body:"$$2.66\\times 11.5=30.590$$"},{title:"Limits",body:"$$UCL=142+30.590=172.59\\qquad LCL=142-30.590=111.41$$"}],final:"111.41 to 172.59 → answer **A**",whyWrong:["","M̄R was used directly as sigma; it must first be divided by d₂ = 1.128 (or multiplied by E₂ = 2.66 = 3 ÷ 1.128).","D₄ = 3.267 is for the MR chart UCL, not the I chart.","The moving range was halved; E₂ already includes the conversion from MR to sigma."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb073",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:1,stem:"For the same I-MR chart (M̄R = **0.9 h**), what are the limits of the **Moving Range** chart? (D₄ = 3.267 for n = 2)",options:["LCL = 0, UCL = 2.394","LCL = −1.80, UCL = 3.60","LCL = −1.494, UCL = 3.294","LCL = 0, UCL = 2.940"],answer:3,hint:"MR chart (n = 2): CL = M̄R, UCL = D₄·M̄R = 3.267·M̄R, LCL = D₃·M̄R = 0.",steps:[{title:"Formula",body:"$$UCL_{MR}=D_4\\,\\overline{MR}=3.267\\times\\overline{MR}\\qquad LCL_{MR}=D_3\\,\\overline{MR}=0$$"},{title:"Compute",body:"$$UCL=3.267\\times 0.9=2.940$$"},{title:"Why LCL = 0",body:"For n = 2, D₃ = 0: a range cannot be negative, so no lower limit exists."}],final:"UCL(MR) = 2.940 → answer **D**",whyWrong:["E₂ = 2.66 is used for the Individuals chart, not the MR chart.","MR limits use D₃ and D₄, not M̄R ± 3·M̄R.","This is M̄R ± 3σ of individuals; the MR chart uses D₃·M̄R and D₄·M̄R.",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb074",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:3,stem:"Six daily values of **average speed of answer (s)** are: 12.4, 13.1, 12.8, 14.0, 13.2, 12.9. What are the Individuals-chart **CL** and **UCL**?",options:["CL = 13.067, UCL = 14.673","CL = 13.067, UCL = 14.822","CL = 13.067, UCL = 14.530","CL = 13.067, UCL = 15.047"],answer:1,hint:"MRᵢ = |xᵢ − xᵢ₋₁|; M̄R = average of the n − 1 moving ranges; UCL = X̄ + 2.66·M̄R.",steps:[{title:"Mean",body:"$$\\bar X=\\dfrac{12.4+13.1+12.8+14.0+13.2+12.9}{6}=13.0667$$"},{title:"Moving ranges",body:"0.7, 0.3, 1.2, 0.8, 0.3 → $$\\overline{MR}=\\dfrac{3.3}{5}=0.6600$$"},{title:"UCL",body:"$$UCL=13.0667+2.66\\times 0.6600=14.822$$"},{title:"Note",body:"Six points are too few for real limits (aim for 20–25); this is a calculation exercise."}],final:"CL 13.067, UCL 14.822 → answer **B**",whyWrong:["The overall sample standard deviation was used; I-chart limits use the average moving range, which reflects short-term variation.","","The sum of the 5 moving ranges was divided by 6 (the number of values); there are only n − 1 = 5 moving ranges.","M̄R was used as sigma; multiply by 2.66 (= 3 ÷ 1.128)."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb075",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"An I-MR chart for **fibre-repair time (h)** has M̄R = **2.256**. What is the estimate of the process σ used for the I chart, and how far is each limit from the centre line?",options:["σ = 2.26; limits are ±6.77 from CL","σ = 2.54; limits are ±7.63 from CL","σ = 2.00; limits are ±6.00 from CL","σ = 2.00; limits are ±4.00 from CL"],answer:2,hint:"σ̂ = M̄R ÷ d₂ (d₂ = 1.128 for n = 2); limits = X̄ ± 3σ̂.",steps:[{title:"Sigma",body:"$$\\hat\\sigma=\\dfrac{\\overline{MR}}{d_2}=\\dfrac{2.256}{1.128}=2.00$$"},{title:"Margin",body:"$$3\\hat\\sigma=3\\times 2.00=6.00$$ — the same as 2.66 × M̄R."}],final:"σ = 2.00, ±6.00 → answer **C**",whyWrong:["M̄R was used as σ without dividing by d₂ = 1.128.","M̄R was multiplied by d₂ instead of divided.","","Control limits are at ±3σ, not ±2σ."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb076",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:1,stem:"An X̄–R chart for **API latency** uses subgroups of **n = 5**. X̿ = **182 ms** and R̄ = **14 ms**. What are the X̄ chart limits? (A₂ = 0.577)",options:["LCL = 140.00, UCL = 224.00","LCL = 152.40, UCL = 211.60","LCL = 178.39, UCL = 185.61","LCL = 173.92, UCL = 190.08"],answer:3,hint:"X̄ chart: X̿ ± A₂·R̄ (A₂ depends on n).",steps:[{title:"Formula",body:"$$UCL=\\bar{\\bar X}+A_2\\bar R\\qquad LCL=\\bar{\\bar X}-A_2\\bar R$$"},{title:"Margin",body:"$$A_2\\bar R=0.577\\times 14=8.0780$$"},{title:"Limits",body:"$$UCL=182+8.0780=190.08\\qquad LCL=182-8.0780=173.92$$"},{title:"Why A₂",body:"$$A_2=\\dfrac{3}{d_2\\sqrt n}$$ converts R̄ to 3 standard errors of the mean."}],final:"173.92 to 190.08 → answer **D**",whyWrong:["R̄ was used as sigma with a factor of 3; the X̄ chart uses A₂·R̄.","D₄ belongs to the R chart, not the X̄ chart.","A₂ already includes the √n adjustment; it must not be divided again.",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb077",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:1,stem:"An X̄–R chart for **API latency** uses subgroups of **n = 5** with R̄ = **14 ms**. What are the **R chart** limits? (D₃ = 0, D₄ = 2.114)",options:["LCL = 5.922, UCL = 22.078","LCL = −1.596, UCL = 29.596","LCL = 0.000, UCL = 29.596","LCL = 0.000, UCL = 56.000"],answer:2,hint:"R chart: CL = R̄, UCL = D₄·R̄, LCL = D₃·R̄.",steps:[{title:"Formula",body:"$$UCL_R=D_4\\bar R\\qquad LCL_R=D_3\\bar R$$"},{title:"Compute",body:"$$UCL=2.114\\times 14=29.596\\qquad LCL=0\\times 14=0.000$$"},{title:"Note",body:"D₃ = 0 for n ≤ 6, so small-subgroup R charts have no lower limit."}],final:"R chart 0.000 to 29.596 → answer **C**",whyWrong:["A₂ is the X̄ chart constant; R chart limits are D₃·R̄ and D₄·R̄.","R̄ minus the upper margin is negative here; a range cannot be negative, so D₃ = 0 and the LCL is 0.","","The UCL is D₄·R̄, not R̄ + 3R̄."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb078",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"An X̄–R chart for **call handle time** uses subgroups of **n = 4**. X̿ = **305 s** and R̄ = **48 s**. What are the X̄ chart limits? (A₂ = 0.729)",options:["LCL = 270.01, UCL = 339.99","LCL = 161.00, UCL = 449.00","LCL = 195.46, UCL = 414.54","LCL = 287.50, UCL = 322.50"],answer:0,hint:"X̄ chart: X̿ ± A₂·R̄ (A₂ depends on n).",steps:[{title:"Formula",body:"$$UCL=\\bar{\\bar X}+A_2\\bar R\\qquad LCL=\\bar{\\bar X}-A_2\\bar R$$"},{title:"Margin",body:"$$A_2\\bar R=0.729\\times 48=34.9920$$"},{title:"Limits",body:"$$UCL=305+34.9920=339.99\\qquad LCL=305-34.9920=270.01$$"},{title:"Why A₂",body:"$$A_2=\\dfrac{3}{d_2\\sqrt n}$$ converts R̄ to 3 standard errors of the mean."}],final:"270.01 to 339.99 → answer **A**",whyWrong:["","R̄ was used as sigma with a factor of 3; the X̄ chart uses A₂·R̄.","D₄ belongs to the R chart, not the X̄ chart.","A₂ already includes the √n adjustment; it must not be divided again."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb079",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:3,stem:"An X̄–R chart for **optical power at the ONT** uses subgroups of **n = 7** with R̄ = **0.85 dBm**. What are the **R chart** limits? (D₃ = 0.076, D₄ = 1.924)",options:["LCL = 0.494, UCL = 1.206","LCL = 0.065, UCL = 1.635","LCL = 0, UCL = 1.635","LCL = 0.065, UCL = 3.400"],answer:1,hint:"R chart: CL = R̄, UCL = D₄·R̄, LCL = D₃·R̄.",steps:[{title:"Formula",body:"$$UCL_R=D_4\\bar R\\qquad LCL_R=D_3\\bar R$$"},{title:"Compute",body:"$$UCL=1.924\\times 0.85=1.635\\qquad LCL=0.076\\times 0.85=0.065$$"},{title:"Note",body:"For n = 7, D₃ > 0, so an unusually small range can also signal (e.g. a stuck sensor or a better process)."}],final:"R chart 0.065 to 1.635 → answer **B**",whyWrong:["A₂ is the X̄ chart constant; R chart limits are D₃·R̄ and D₄·R̄.","","For n = 7, D₃ = 0.076 is not zero, so the R chart has a positive LCL.","The UCL is D₄·R̄, not R̄ + 3R̄."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb080",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:3,stem:`Four subgroups (n = 5) of **ticket triage time** were collected:

| Subgroup | Values (min) |
|---|---|
| 1 | 22, 25, 24, 27, 23 |
| 2 | 26, 24, 25, 28, 24 |
| 3 | 21, 23, 26, 24, 22 |
| 4 | 25, 27, 24, 26, 25 |

Using A₂ = 0.577, what are X̿, R̄ and the X̄ chart UCL?`,options:["X̿ = 24.55, R̄ = 4.25, UCL = 27.00","X̿ = 24.55, R̄ = 1.67, UCL = 25.51","X̿ = 24.55, R̄ = 7.00, UCL = 28.59","X̿ = 24.55, R̄ = 4.25, UCL = 33.53"],answer:0,hint:"X̄ᵢ and Rᵢ per subgroup; X̿ = mean of X̄ᵢ; R̄ = mean of Rᵢ; UCL = X̿ + A₂R̄.",steps:[{title:"Subgroup means",body:"24.2, 25.4, 23.2, 25.4"},{title:"Subgroup ranges",body:"5, 4, 5, 3"},{title:"Grand values",body:"$$\\bar{\\bar X}=\\dfrac{24.2+25.4+23.2+25.4}{4}=24.55\\qquad \\bar R=\\dfrac{5+4+5+3}{4}=4.25$$"},{title:"UCL",body:"$$UCL=24.55+0.577\\times 4.25=27.00$$"}],final:"UCL = 27.00 → answer **A**",whyWrong:["","The average standard deviation was used instead of the average range.","The overall range of all 20 values was used; R̄ is the average of the subgroup ranges.","D₄ (2.114) was used instead of A₂ (0.577)."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb081",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"An X̄–S chart for **hourly average chat wait** uses subgroups of **n = 10**. X̿ = **64 s** and S̄ = **9.5 s**. What are the X̄ chart limits? (A₃ = 0.975)",options:["LCL = 61.07, UCL = 66.93","LCL = 54.74, UCL = 73.26","LCL = 35.50, UCL = 92.50","LCL = 47.70, UCL = 80.30"],answer:1,hint:"X̄–S: X̄ limits = X̿ ± A₃·S̄.",steps:[{title:"Formula",body:"$$UCL=\\bar{\\bar X}+A_3\\bar S\\qquad LCL=\\bar{\\bar X}-A_3\\bar S$$"},{title:"Compute",body:"$$A_3\\bar S=0.975\\times 9.5=9.2625$$ → UCL = 73.26, LCL = 54.74."},{title:"Why A₃",body:"$$A_3=\\dfrac{3}{c_4\\sqrt n}$$"}],final:"54.74 to 73.26 → answer **B**",whyWrong:["A₂ is for R̄; with S̄ the constant is A₃.","","S̄ estimates σ of individuals; the X̄ chart needs the standard error (A₃ includes c₄ and √n).","B₄ belongs to the S chart."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb082",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"An X̄–S chart for **hourly average chat wait** uses subgroups of **n = 10** with S̄ = **9.5 s**. What are the **S chart** limits? (B₃ = 0.284, B₄ = 1.716)",options:["LCL = 2.119, UCL = 16.881","LCL = 0, UCL = 16.302","LCL = 2.698, UCL = 16.302","LCL = 0.238, UCL = 18.762"],answer:2,hint:"S chart: CL = S̄, UCL = B₄·S̄, LCL = B₃·S̄.",steps:[{title:"Formula",body:"$$UCL_S=B_4\\bar S\\qquad LCL_S=B_3\\bar S$$"},{title:"Compute",body:"$$UCL=1.716\\times 9.5=16.302\\qquad LCL=0.284\\times 9.5=2.698$$"}],final:"S chart 2.698 to 16.302 → answer **C**",whyWrong:["D₃ and D₄ are for range charts; S charts use B₃ and B₄.","For n = 10, B₃ = 0.284 > 0, so the LCL is not zero.","","A₃ is the X̄ chart constant; the S chart uses B₃·S̄ and B₄·S̄."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb083",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:3,stem:"An X̄–S chart for **DNS response time** uses subgroups of **n = 6** with S̄ = **4.2 ms**. What are the **S chart** limits? (B₃ = 0.03, B₄ = 1.97)",options:["LCL = 0.000, UCL = 8.417","LCL = 0, UCL = 8.274","LCL = −1.205, UCL = 9.605","LCL = 0.126, UCL = 8.274"],answer:3,hint:"S chart: CL = S̄, UCL = B₄·S̄, LCL = B₃·S̄.",steps:[{title:"Formula",body:"$$UCL_S=B_4\\bar S\\qquad LCL_S=B_3\\bar S$$"},{title:"Compute",body:"$$UCL=1.97\\times 4.2=8.274\\qquad LCL=0.03\\times 4.2=0.126$$"}],final:"S chart 0.126 to 8.274 → answer **D**",whyWrong:["D₃ and D₄ are for range charts; S charts use B₃ and B₄.","For n = 6, B₃ = 0.03 > 0, so the LCL is not zero.","A₃ is the X̄ chart constant; the S chart uses B₃·S̄ and B₄·S̄.",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb084",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"A team inspects **200 orders per day** for **20 days** (4000 in total) and finds **96 defective orders**. What are the p chart CL and UCL?",options:["CL = 0.024, UCL = 0.0313","CL = 0.024, UCL = 0.0569","CL = 0.024, UCL = 0.0565","CL = 4.800, UCL = 11.2933"],answer:2,hint:"p̄ = total defectives ÷ total inspected; limits = p̄ ± 3√(p̄(1 − p̄) ÷ n).",steps:[{title:"Centre line",body:"$$\\bar p=\\dfrac{96}{4000}=0.024$$"},{title:"Standard error",body:"$$\\sqrt{\\dfrac{0.024\\times 0.976}{200}}=0.01082$$"},{title:"Limits",body:"$$UCL=0.024+3\\times 0.01082=0.0565\\qquad LCL=0.024-0.0325=-0.0085\\rightarrow 0$$"},{title:"Note",body:"A negative LCL is set to 0."}],final:"CL 0.024, UCL 0.0565 → answer **C**",whyWrong:["The total inspected (4,000) was used in the formula; each point is a daily proportion based on n = 200.","The (1 − p̄) factor was dropped; that is the u chart form.","","This is an np chart (counts per day), not a p chart (proportions)."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb085",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"A p chart of **failed SIM activations** has p̄ = **0.05**. On one day only **80** activations were attempted. What are that day’s control limits?",options:["LCL = −0.0231, UCL = 0.1231","LCL = 0, UCL = 0.0962","LCL = 0, UCL = 0.7038","LCL = 0, UCL = 0.1231"],answer:3,hint:"Variable n: limits for subgroup i = p̄ ± 3√(p̄(1 − p̄) ÷ nᵢ); negative LCL → 0.",steps:[{title:"Standard error",body:"$$\\sqrt{\\dfrac{0.05\\times 0.95}{80}}=0.02437$$"},{title:"Limits",body:"$$UCL=0.05+3\\times 0.02437=0.1231\\qquad LCL=0.05-0.0731=-0.0231\\rightarrow 0$$"},{title:"Note",body:"Small subgroups get wide limits; that is why p-chart limits step up and down."}],final:"0 to 0.1231 → answer **D**",whyWrong:["The calculated LCL is negative, and a proportion cannot be negative, so it is set to 0.","The average daily size was used; with varying n each day gets its own limits from its own nᵢ.","The division by nᵢ was left out of the standard error.",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb086",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"A p chart for **first-time-fix failures** has p̄ = **0.08** and n = **150** jobs per day. Today **24** jobs failed. Is today out of control?",options:["No — p = 0.1600 is below the UCL of 0.8939","Yes — p = 0.1600 is above the UCL of 0.1465","Yes — but only because p exceeds the 2σ warning line at 0.1243","No — p = 0.1600 is below p̄ + 3 × p̄ = 0.32"],answer:1,hint:"Compare the day’s proportion with p̄ ± 3√(p̄(1 − p̄) ÷ n).",steps:[{title:"Today",body:"$$p=\\dfrac{24}{150}=0.1600$$"},{title:"UCL",body:"$$UCL=0.08+3\\sqrt{\\dfrac{0.08\\times 0.92}{150}}=0.08+3\\times 0.02215=0.1465$$"},{title:"Decide",body:"0.1600 > 0.1465 → out of control (Test 1). Investigate today’s jobs."}],final:"Out of control → answer **B**",whyWrong:["The division by n was left out of the standard error, giving a UCL that is far too wide.","","Control limits are at 3 standard errors; the conclusion must be based on the 3σ UCL.","Limits use 3 standard errors, not 3 × p̄."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb087",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"An np chart tracks **rejected port-in requests (n = 250 per day)**. The long-run proportion defective is p̄ = **0.04**. What are the CL and limits?",options:["CL = 10.0, LCL = 0.70, UCL = 19.30","CL = 10.0, LCL = 0.51, UCL = 19.49","CL = 0.040, LCL = 0.0028, UCL = 0.0772","CL = 10.0, LCL = 0.00, UCL = 38.80"],answer:0,hint:"np chart: CL = np̄; limits = np̄ ± 3√(np̄(1 − p̄)); negative LCL → 0.",steps:[{title:"Centre line",body:"$$n\\bar p=250\\times 0.04=10.0$$"},{title:"Sigma",body:"$$\\sqrt{n\\bar p(1-\\bar p)}=\\sqrt{10.0\\times 0.96}=3.0984$$"},{title:"Limits",body:"$$UCL=10.0+3\\times 3.0984=19.30\\qquad LCL=10.0-9.2952=0.70$$"}],final:"CL 10.0, UCL 19.30 → answer **A**",whyWrong:["","The (1 − p̄) factor was dropped; √(np̄) is the c-chart form.","These are p chart limits (proportions); an np chart plots counts.","The variance np̄(1 − p̄) was used without taking the square root."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb088",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"An np chart tracks **mis-routed calls (n = 400 per shift)**. The long-run proportion defective is p̄ = **0.025**. What are the CL and limits?",options:["CL = 10.0, LCL = 0.63, UCL = 19.37","CL = 10.0, LCL = 0.51, UCL = 19.49","CL = 0.025, LCL = 0.0016, UCL = 0.0484","CL = 10.0, LCL = 0.00, UCL = 39.25"],answer:0,hint:"np chart: CL = np̄; limits = np̄ ± 3√(np̄(1 − p̄)); negative LCL → 0.",steps:[{title:"Centre line",body:"$$n\\bar p=400\\times 0.025=10.0$$"},{title:"Sigma",body:"$$\\sqrt{n\\bar p(1-\\bar p)}=\\sqrt{10.0\\times 0.975}=3.1225$$"},{title:"Limits",body:"$$UCL=10.0+3\\times 3.1225=19.37\\qquad LCL=10.0-9.3675=0.63$$"}],final:"CL 10.0, UCL 19.37 → answer **A**",whyWrong:["","The (1 − p̄) factor was dropped; √(np̄) is the c-chart form.","These are p chart limits (proportions); an np chart plots counts.","The variance np̄(1 − p̄) was used without taking the square root."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb089",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:1,stem:"Over **30 days**, a team counted **270** customer-premises faults in a region with a constant number of lines. What are the **c chart** limits?",options:["CL = 9.0, LCL = 6.0, UCL = 12.0","CL = 9.0, LCL = 0.0, UCL = 18.0","CL = 9.0, LCL = 0, UCL = 36.0","CL = 270.0, LCL = 220.7, UCL = 319.3"],answer:1,hint:"c chart: c̄ = total defects ÷ number of periods; limits = c̄ ± 3√c̄.",steps:[{title:"Centre line",body:"$$\\bar c=\\dfrac{270}{30}=9.0$$"},{title:"Sigma",body:"$$\\sqrt{\\bar c}=\\sqrt{9.0}=3.0$$"},{title:"Limits",body:"$$UCL=9.0+3\\times 3.0=18.0\\qquad LCL=9.0-9.0=0.0$$"}],final:"c chart 0.0 to 18.0 → answer **B**",whyWrong:["Only one √c̄ was used; limits are ±3√c̄.","","c̄ was used as the standard deviation; for a Poisson count σ = √c̄.","The total was used as the centre line; c̄ is the average count per day."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb090",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"A c chart of **software defects found per release test cycle** has c̄ = **12**. The latest value is **24**. Is it beyond the UCL?",options:["No — UCL = 48.00, so 24 is inside","No — a single point cannot signal on a c chart","Yes — UCL = 22.39, so 24 signals","Yes — UCL = 18.93, so 24 signals"],answer:2,hint:"c chart UCL = c̄ + 3√c̄.",steps:[{title:"UCL",body:"$$UCL=12+3\\sqrt{12}=12+3\\times 3.4641=22.39$$"},{title:"Compare",body:"24 > 22.39 → signal: investigate."}],final:"Signal → answer **C**",whyWrong:["c̄ was used as sigma; for counts σ = √c̄.","Test 1 (one point beyond a control limit) applies to attribute charts as well.","","The answer is right but the UCL is c̄ + 3√c̄, not 2√c̄."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb091",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:3,stem:"A c chart of **dropped calls per 10,000 attempts per cell per day** has c̄ = **2.5**. The latest value is **8**. Is it beyond the UCL?",options:["No — UCL = 10.00, so 8 is inside","No — a single point cannot signal on a c chart","Yes — UCL = 5.66, so 8 signals","Yes — UCL = 7.24, so 8 signals"],answer:3,hint:"c chart UCL = c̄ + 3√c̄.",steps:[{title:"UCL",body:"$$UCL=2.5+3\\sqrt{2.5}=2.5+3\\times 1.5811=7.24$$"},{title:"Compare",body:"8 > 7.24 → signal: investigate."}],final:"Signal → answer **D**",whyWrong:["c̄ was used as sigma; for counts σ = √c̄.","Test 1 (one point beyond a control limit) applies to attribute charts as well.","The answer is right but the UCL is c̄ + 3√c̄, not 2√c̄.",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb092",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"A u chart tracks **billing errors per 100 invoices** with ū = **1.8**. One subgroup covers **4** units of opportunity (nᵢ = 4). What are its control limits?",options:["LCL = 0.000, UCL = 5.825","LCL = 0.450, UCL = 3.150","LCL = 0.000, UCL = 3.622","LCL = 0.000, UCL = 3.812"],answer:3,hint:"u chart: limits for subgroup i = ū ± 3√(ū ÷ nᵢ); negative LCL → 0.",steps:[{title:"Standard error",body:"$$\\sqrt{\\dfrac{\\bar u}{n_i}}=\\sqrt{\\dfrac{1.8}{4}}=0.6708$$"},{title:"Limits",body:"$$UCL=1.8+3\\times 0.6708=3.812\\qquad LCL=1.8-2.0125=-0.212\\rightarrow 0$$"},{title:"Note",body:"Limits vary with nᵢ: bigger areas of opportunity give tighter limits."}],final:"0.000 to 3.812 → answer **D**",whyWrong:["The division by nᵢ was left out; that is the c chart form.","The square root was not taken: σ = √(ū ÷ nᵢ).","A (1 − p) style factor was added; defects per unit follow a Poisson model with no such factor.",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb093",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:3,stem:"A u chart tracks **faults per km of fibre route** with ū = **0.6**. One subgroup covers **25** units of opportunity (nᵢ = 25). What are its control limits?",options:["LCL = 0.000, UCL = 2.924","LCL = 0.528, UCL = 0.672","LCL = 0.135, UCL = 1.065","LCL = 0.149, UCL = 1.051"],answer:2,hint:"u chart: limits for subgroup i = ū ± 3√(ū ÷ nᵢ); negative LCL → 0.",steps:[{title:"Standard error",body:"$$\\sqrt{\\dfrac{\\bar u}{n_i}}=\\sqrt{\\dfrac{0.6}{25}}=0.1549$$"},{title:"Limits",body:"$$UCL=0.6+3\\times 0.1549=1.065\\qquad LCL=0.6-0.4648=0.135$$"},{title:"Note",body:"Limits vary with nᵢ: bigger areas of opportunity give tighter limits."}],final:"0.135 to 1.065 → answer **C**",whyWrong:["The division by nᵢ was left out; that is the c chart form.","The square root was not taken: σ = √(ū ÷ nᵢ).","","A (1 − p) style factor was added; defects per unit follow a Poisson model with no such factor."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb094",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:1,stem:"Over 20 days, **156** configuration errors were found in **120** router builds (builds per day varied). What is ū, the u chart centre line?",options:["7.80","1.30","0.77","0.065"],answer:1,hint:"ū = total defects ÷ total units inspected (not the average of daily u values when sizes differ).",steps:[{title:"Formula",body:"$$\\bar u=\\dfrac{\\sum c_i}{\\sum n_i}$$"},{title:"Compute",body:"$$\\bar u=\\dfrac{156}{120}=1.30$$ errors per build."}],final:"ū = 1.30 → answer **B**",whyWrong:["Total defects were divided by the number of days; ū is defects per unit (per build).","","The ratio was inverted: ū = defects ÷ units.","ū was divided again by the number of days; it is already a per-unit rate."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb095",phase:5,topic:"5.2.13",qtype:"concept",difficulty:2,stem:"Why is the R chart **LCL equal to 0** for subgroups of size 6 or less?",options:["Because D₃ = 0 for n ≤ 6: the calculated lower limit would be negative, and a range cannot be negative","Because small subgroups never have small ranges","Because R charts only detect increases in variation by definition","Because Minitab rounds all small limits to zero"],answer:0,hint:"D₃ = max(0, 1 − 3d₃ ÷ d₂) → 0 for n ≤ 6.",steps:[{title:"Key idea",body:"For small n, R̄ − 3σ_R is below zero. Since ranges cannot be negative, the LCL is set to 0 (D₃ = 0)."},{title:"Consequence",body:"Small-n R charts cannot signal an improvement (reduced spread) through Test 1."}],final:"D₃ = 0 for n ≤ 6 → answer **A**",whyWrong:["","Small subgroups can have very small ranges; the point is the limit formula.","R charts with n ≥ 7 do have a positive LCL and can detect decreases.","It is a property of the constants, not rounding."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb096",phase:5,topic:"5.2.13",qtype:"best-action",difficulty:2,stem:"A team calculates I-chart limits for **daily order volume** using the **overall standard deviation** of 60 days, during which a known step change happened. The chart shows no signals. What is the BEST correction?",options:["Keep the overall standard deviation because it uses all the data","Use specification limits instead","Use ±2σ limits to compensate","Recalculate the limits using the average moving range (σ = M̄R ÷ 1.128), which reflects short-term variation and is not inflated by the step change"],answer:3,hint:"Control limits use short-term (within) variation: R̄ ÷ d₂, S̄ ÷ c₄ or M̄R ÷ 1.128.",steps:[{title:"Key idea",body:"The overall SD includes between-period differences, including special causes. Limits based on it are too wide."},{title:"Fix",body:"Use the moving-range estimate, which mostly reflects point-to-point (common-cause) variation."}],final:"Use M̄R-based limits → answer **D**",whyWrong:["The overall SD includes the shift itself, which widens the limits and hides the shift.","Specifications are not control limits.","Changing the multiplier does not fix the wrong σ estimate.",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb097",phase:5,topic:"5.2.13",qtype:"scenario",difficulty:2,stem:"Which chart should be used for the **number of defective SIM cards** found in daily samples of **varying size**?",options:["np chart","c chart","p chart","I-MR chart"],answer:2,hint:"Defectives (pass/fail units): constant n → np or p; varying n → p.",steps:[{title:"Key idea",body:"Each card is either defective or not (binomial). Varying sample size means plotting proportions with limits that depend on nᵢ."},{title:"Formula",body:"p̄ ± 3√(p̄(1 − p̄) ÷ nᵢ)."}],final:"p chart → answer **C**",whyWrong:["np charts need a constant sample size.","c charts count defects (not defective units) with a constant area of opportunity.","","Proportions with varying n are better handled with binomial-based p charts."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb098",phase:5,topic:"5.2.13",qtype:"scenario",difficulty:2,stem:"Which chart fits the **number of errors per invoice batch**, where each batch contains a **different number of invoices** and an invoice can have several errors?",options:["u chart","p chart","c chart","np chart"],answer:0,hint:"Defects (counts): constant area → c chart; varying area → u chart.",steps:[{title:"Key idea",body:"Errors are defects (Poisson counts). Because batch sizes vary, divide by the number of invoices to get errors per invoice."},{title:"Formula",body:"ū ± 3√(ū ÷ nᵢ)."}],final:"u chart → answer **A**",whyWrong:["","p charts are for defective units (yes/no), not for counts of defects that can exceed one per unit.","c charts need a constant area of opportunity; batch sizes vary here.","np charts count defective units in constant-size samples."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb099",phase:5,topic:"5.2.13",qtype:"not-except",difficulty:2,stem:"All of the following constant pairings are correct EXCEPT:",options:["X̄ chart with R̄ uses A₂","S chart limits use D₃ and D₄","X̄ chart with S̄ uses A₃","MR chart uses D₄ = 3.267 for n = 2"],answer:1,hint:"R chart: D₃, D₄. S chart: B₃, B₄. X̄ with R: A₂. X̄ with S: A₃. I chart: E₂ = 2.66.",steps:[{title:"Key idea",body:"Each chart has its own constants because each statistic has a different sampling distribution."},{title:"Odd one out",body:"S charts use B₃ and B₄."}],final:"S chart uses B₃, B₄ → answer **B**",whyWrong:["Correct: X̿ ± A₂R̄.","","Correct: X̿ ± A₃S̄.","Correct: UCL = 3.267·M̄R."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb100",phase:5,topic:"5.2.13",qtype:"true-false",difficulty:1,stem:"True or false: the control-chart constants A₂, D₃ and D₄ depend on the subgroup size n.",options:["True","False"],answer:0,hint:"Constants are looked up by n.",steps:[{title:"Key idea",body:"For example, A₂ = 0.729 for n = 4 and 0.577 for n = 5."},{title:"Trap",body:"Using the constant for the wrong n gives wrong limits."}],final:"True → answer **True**",whyWrong:["","They are derived from d₂ and d₃, which depend on n, so a different table row is used for each subgroup size."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb101",phase:5,topic:"5.2.13",qtype:"true-false",difficulty:2,stem:"True or false: if a calculated LCL for a p chart is negative, the analyst should keep the negative value on the chart.",options:["True","False"],answer:1,hint:"Negative LCL for p, np, c, u (and R with small n) → 0.",steps:[{title:"Key idea",body:"The normal approximation gives a negative number when p̄ is small or n is small."},{title:"Apply",body:"Draw the LCL at 0 and rely on run rules for downward patterns."}],final:"False → answer **False**",whyWrong:["A proportion cannot be negative, so the LCL is set to 0 (and the chart has effectively no lower limit).",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb102",phase:5,topic:"5.2.13",qtype:"concept",difficulty:2,stem:"When should **control limits be recalculated**?",options:["After a deliberate, verified process change (e.g. an improvement), using enough new data from the changed process","Every week, so that the limits always match the latest data","Whenever a point falls outside the limits","Only when the specification limits change"],answer:0,hint:"Freeze limits in Phase II; recalculate only for a known, sustained change.",steps:[{title:"Key idea",body:"Limits describe a stable process. If the process is deliberately changed and the new level is stable (e.g. 20–25 new subgroups), new limits are justified."},{title:"Document",body:"Mark the change point and the date of new limits on the chart."}],final:"After a verified process change → answer **A**",whyWrong:["","Constant recalculation lets the limits follow the process and hides real shifts.","A signal calls for investigation, not for moving the limits.","Specifications and control limits are independent."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb103",phase:5,topic:"5.2.13",qtype:"concept",difficulty:2,stem:"Why is the I-chart constant E₂ equal to **2.66**?",options:["Because 2.66 is the 99% point of the normal distribution","Because the limits are X̄ ± 3σ and σ is estimated by M̄R ÷ d₂ with d₂ = 1.128 for n = 2, so 3 ÷ 1.128 ≈ 2.66","Because I charts use ±2.66σ limits instead of ±3σ","Because it equals D₄ for n = 2"],answer:1,hint:"E₂ = 3 ÷ d₂(2) = 3 ÷ 1.128.",steps:[{title:"Derivation",body:"$$\\bar X\\pm 3\\hat\\sigma=\\bar X\\pm 3\\times\\dfrac{\\overline{MR}}{1.128}=\\bar X\\pm 2.66\\,\\overline{MR}$$"},{title:"Use",body:"Same logic as A₂ = 3 ÷ (d₂√n) for X̄ charts."}],final:"3 ÷ 1.128 → answer **B**",whyWrong:["The 99.5% point is about 2.58; E₂ comes from 3 ÷ d₂.","","I charts use ±3σ; 2.66 multiplies M̄R, not σ.","D₄ for n = 2 is 3.267."],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb104",phase:5,topic:"5.2.13",qtype:"statements",difficulty:2,stem:`Which statements about centre lines are correct?

1. The centre line of a p chart is total defectives ÷ total inspected.
2. The centre line of an R chart is the average range R̄.
3. The centre line of an np chart is p̄.
4. The centre line of a u chart is total defects ÷ total units.`,options:["1 and 3 only","2, 3 and 4 only","1, 2, 3 and 4","1, 2 and 4 only"],answer:3,hint:"CL = average of the plotted statistic, weighted by sample size where sizes vary.",steps:[{title:"Check each",body:"1 True. 2 True. 3 False — np̄. 4 True."},{title:"Decide",body:"Statements 1, 2 and 4."}],final:"1, 2, 4 → answer **D**",whyWrong:["Statement 3 is false (the np chart CL is np̄); statements 2 and 4 are true.","Statement 3 is false and statement 1 is true.","Statement 3 is false: an np chart plots counts, so its CL is n × p̄.",""],bookRef:"Syllabus 5.2.13"},{id:"sv-5-bb105",phase:5,topic:"5.2.13",qtype:"calculation",difficulty:2,stem:"An X̄–S chart of **hourly chat wait time** (n = 10) has S̄ = **9.5 s**. What is the estimate of the process (within-subgroup) σ? (c₄ = 0.9727)",options:["9.241 s","3.004 s","9.767 s","9.500 s"],answer:2,hint:"σ̂ = S̄ ÷ c₄ (c₄ < 1 corrects the bias of the sample standard deviation).",steps:[{title:"Formula",body:"$$\\hat\\sigma=\\dfrac{\\bar S}{c_4}$$"},{title:"Compute",body:"$$\\hat\\sigma=\\dfrac{9.5}{0.9727}=9.767$$"},{title:"Link",body:"$$A_3=\\dfrac{3}{c_4\\sqrt n}$$ uses the same correction inside the X̄ limits."}],final:"σ = 9.767 s → answer **C**",whyWrong:["S̄ was multiplied by c₄; it must be divided, because S̄ underestimates σ on average.","This divides by √n, which gives a standard error, not σ.","","S̄ is a slightly biased estimate of σ; the c₄ correction is needed."],bookRef:"Syllabus 5.2.13"}];export{e as items};
